-- quest_extra.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[9632] = {id=9632,name="Newfound Allies",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=3524,mapID=97,description="Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, , but our enemies are many and our resources few. Our weakness is well known to our enemies, but your contact with the forces of the Alliance is something they haven't accounted for. I have prepared a letter of introduction to the people of Auberdine, the closest Alliance settlement, proposing cooperation in the fight against our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of the Exodar.",starts={{npcID=17424,x=0.546,y=0.54,mapID=106}},ends={{npcID=17614,x=0.242,y=0.542,mapID=97}},coords={x=0.546,y=0.54,source="quest_giver",mapID=97},questType="standard"},
[9708] = {id=9708,name="Familiar Fungi",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3521,mapID=102,description="Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere in the marsh! To the north is a place known as the Hewn Bog. Odd name for the place if you ask me, but I've never been there. I'll need samples of those mushrooms to confirm my hypothesis. Just be careful, . I'd heard that ogres have moved in to the area, so you'll have to get the samples from them. Could that be why the bog lords are no longer going there for their food?",starts={{npcID=17831,x=0.232,y=0.662,mapID=102}},ends={{npcID=17831,x=0.232,y=0.662,mapID=102}},coords={x=0.232,y=0.662,source="quest_giver",mapID=102},questType="standard"},
[10238] = {id=10238,name="How to Serve Goblins",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3483,mapID=100,description="Why would fel orcs steal my shredder parts? I hate them so much. They just sneak into my camp here and take things all the time. A couple of days ago they stole three of my peons! Now the rest of my peons have run off because they are afraid they are going to be eaten by fel orcs. I can't run a mine without peons. If you could save the peons that I lost maybe the others would come back. The fel orcs have their camps along the wall to the southwest.",starts={{npcID=16915,x=0.512,y=0.306,mapID=100}},ends={{npcID=16915,x=0.512,y=0.306,mapID=100}},coords={x=0.512,y=0.306,source="quest_giver",mapID=100},questType="standard"},
[10255] = {id=10255,name="Testing the Antidote",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3483,mapID=100,description="I think there's something we can use in the blood as the base of an antidote. Don't look at me like I've lost my mind! It's a common theme in nature. Often, the cure for something can be derived from the toxin itself. That's just what I aim to do. Ridding the boars of their demonic influence would probably eliminate their aggression and give us insight into how to best attempt to help other species.",starts={{npcID=16991,x=0.156,y=0.522,mapID=100}},ends={{npcID=16991,x=0.156,y=0.522,mapID=100}},coords={x=0.156,y=0.522,source="quest_giver",mapID=100},questType="standard"},
[10839] = {id=10839,name="Veil Skith: Darkstone of Terokk",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3519,mapID=108,description="Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed. Take this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.",starts={{npcID=22272,x=0.374,y=0.514,mapID=108}},ends={{npcID=22272,x=0.374,y=0.514,mapID=108}},coords={x=0.374,y=0.514,source="quest_giver",mapID=108},questType="standard"},
[10900] = {id=10900,name="The Mark of Vashj",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3717,questType="raid"},
[10920] = {id=10920,name="For the Fallen",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3519,mapID=108,description="When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle. We pursued the creatures into the night. Some of our people we found dead in the dark, others we could hear struggling against their captors. By morning we had come to this place and we fought a fierce battle but we were beaten. Dreadfang poison will soon take my companions and I cannot last long. Before I die I must know that the dreadfang widows were beaten.",starts={{npcID=22462,x=0.496,y=0.762,mapID=108}},ends={{npcID=22462,x=0.496,y=0.762,mapID=108}},coords={x=0.496,y=0.762,source="quest_giver",mapID=108},questType="standard"},
[29404] = {id=29404,name="Much to Learn",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi.",questType="standard"},
[29405] = {id=29405,name="The Lesson of the Iron Staff",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="To train, first you must be properly equipped. Retrieve a weapon from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.",questType="standard"},
[29407] = {id=29407,name="The First Sign of Winter",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="At the stream below rests a single lotus flower. Within this lotus lies a sign of things to come. Bring it to me that I might show you.",questType="standard"},
[29432] = {id=29432,name="Delegation Tracker",level=5,requiredLevel=5,faction="both",expansion=4,zoneID=616,mapID=198,description="I am duty-bound to look into your claims immediately, , which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the world tree's branch.",questType="raid"},
[29441] = {id=29441,name="From the Belly of the Beast",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=130,mapID=21,questType="standard"},
[29475] = {id=29475,name="Goblin Engineering",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=1638,mapID=88,description="A skilled engineer can choose ONE specialization, and I know the secrets of goblin engineering. You look like you're ready to blow things up, but I'll need some samples of your work. Bring me twenty big iron bombs , twenty sticks of solid dynamite , and five explosive sheep . Submit these items to an engineering trainer in any of the capital cities and you'll be an official goblin engineer with access to all the schematics!",starts={{npcID=5174,x=0.684,y=0.442,mapID=87},{npcID=5518,x=0.628,y=0.32,mapID=84},{npcID=11017,x=0.568,y=0.564,mapID=85},{npcID=52651,x=0.364,y=0.596,mapID=88}},ends={{npcID=5174,x=0.684,y=0.442,mapID=87},{npcID=5518,x=0.628,y=0.32,mapID=84},{npcID=11017,x=0.568,y=0.564,mapID=85},{npcID=52651,x=0.364,y=0.596,mapID=88}},coords={x=0.684,y=0.442,source="quest_giver",mapID=88},questType="standard"},
[29482] = {id=29482,name="Transmutation Master",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=1497,mapID=90,description="Iron to gold, water to fire... if you want to become an transmutation master , then I can show you the way. The training is very expensive, so you'll have to bring me some of the finest transmuted materials in the world. Remember , you can only learn ONE specialization, so if you complete your transmutation training, then potion and elixir specialization will no longer be available.",starts={{npcID=3347,x=0.556,y=0.458,mapID=85},{npcID=5177,x=0.666,y=0.55,mapID=87},{npcID=5499,x=0.556,y=0.858,mapID=84}},ends={{npcID=3347,x=0.556,y=0.458,mapID=85},{npcID=5177,x=0.666,y=0.55,mapID=87},{npcID=5499,x=0.556,y=0.858,mapID=84},{npcID=4611,x=0.476,y=0.728,mapID=90}},coords={x=0.556,y=0.458,source="quest_giver",mapID=90},questType="standard"},
[29531] = {id=29531,name="Kill Stuff",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=151,description="I really need you to kill some stuff for me. It's pretty important.",questType="standard"},
[29534] = {id=29534,name="Collect Things",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=151,description="The Quest Wizard demands Stuff Tails ! Go now and fetch them.",questType="standard"},
[29541] = {id=29541,name="Take Care of It",level=5,requiredLevel=5,faction="both",expansion=4,questType="standard"},
[29601] = {id=29601,name="The Darkmoon Field Guide",level=1,requiredLevel=1,faction="none",expansion=4,description="Do you have a copy of the Darkmoon Field Guide, friend? It's a most useful book to carry with you. It can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you've found your five hundredth brass button or that rare treasure the Darkmoon Faire's collectors crave.",questType="standard"},
[29693] = {id=29693,name="The General's Edge",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="As you gradually gather your senses and begin to take in your surroundings, this object stands out amongst the strewn wreckage. It occurs to you that this is the first time you've seen Nazgrim's axe outside of his tight grasp. Somehow, this fact makes your predicament even more unsettling... You know that dead or alive, the General would want his weapon back in his possession.",questType="standard"},
[29696] = {id=29696,name="My Stars!",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="A number of Kiryn's articles have been scattered around the area by wood sprites, but this one stands out as important to you. The bag once hung from her waist, loaded with throwing stars. Without them, her arsenal will be considerably diminished. If you were to retrieve the weapons from the pests that inhabit this region, it could only help your cause.",questType="standard"},
[29703] = {id=29703,name="Barrel of Monkies",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,mapID=378,description="These monkeymen are driving me insane! I was just trying to get some insight into panderan brewing tactics and these hozu things keep drinking the brews before I can properly chemical test them. Can you please go take a few of them out as a lesson to the others? I'll make it worth your while.",questType="standard"},
[29715] = {id=29715,name="The Witch in the Woods",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[29722] = {id=29722,name="A Lesson in Bravery",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[29728] = {id=29728,name="Explosive Evidence",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="I must ask you to do one more thing for me, . The personal effects on this ship cannot be left for others to find. We'll have to destroy it. I cobbled together some Makeshift Dynamite from the scraps you brought me. Place the dynamite anywhere on the ship, but take care not to put them too close together. They might be...uh...a little unwieldy, so you should spread them out in case of premature detonation.",questType="standard"},
[29732] = {id=29732,name="What Goes Down, Must Come Up!",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="Rivett left behind what looks to be an important piece of equipment. Along its shaft you are able to make out the words: Goblin Drone Dispenser . With a simple calibration, the device is set to deliver drones to Nazgrim's basecamp. Easy enough.... There's just one problem. The only supply crates worth transporting have fallen to the cliff ledge below the crash impact. As you ponder the issue, you see the long, coiled tail of a Cliff Glider fly by the corner of your eye...",questType="standard"},
[29734] = {id=29734,name="Deepforge the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5042,mapID=207,starts={{npcID=55216,x=0.276,y=0.692,mapID=207}},ends={{npcID=55216,x=0.276,y=0.692,mapID=207}},coords={x=0.276,y=0.692,source="quest_giver",mapID=207},questType="standard"},
[29735] = {id=29735,name="Stonebrand the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5042,mapID=207,starts={{npcID=55217,x=0.496,y=0.548,mapID=207}},ends={{npcID=55217,x=0.496,y=0.548,mapID=207}},coords={x=0.496,y=0.548,source="quest_giver",mapID=207},questType="standard"},
[29736] = {id=29736,name="Darkfeather the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=4922,mapID=241,starts={{npcID=55218,x=0.518,y=0.33,mapID=241}},ends={{npcID=55218,x=0.518,y=0.33,mapID=241}},coords={x=0.518,y=0.33,source="quest_giver",mapID=241},questType="standard"},
[29737] = {id=29737,name="Firebeard the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=4922,mapID=241,starts={{npcID=55219,x=0.508,y=0.704,mapID=241}},ends={{npcID=55219,x=0.508,y=0.704,mapID=241}},coords={x=0.508,y=0.704,source="quest_giver",mapID=241},questType="standard"},
[29738] = {id=29738,name="Moonlance the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5144,mapID=205,starts={{npcID=55228,x=0.572,y=0.862,mapID=205}},ends={{npcID=55228,x=0.572,y=0.862,mapID=205}},coords={x=0.572,y=0.862,source="quest_giver",mapID=205},questType="standard"},
[29739] = {id=29739,name="Windsong the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=616,mapID=198,starts={{npcID=55224,x=0.266,y=0.62,mapID=198}},ends={{npcID=55224,x=0.266,y=0.62,mapID=198}},coords={x=0.266,y=0.62,source="quest_giver",mapID=198},questType="standard"},
[29740] = {id=29740,name="Evershade the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=616,mapID=198,starts={{npcID=55227,x=0.626,y=0.228,mapID=198}},ends={{npcID=55227,x=0.626,y=0.228,mapID=198}},coords={x=0.626,y=0.228,source="quest_giver",mapID=198},questType="standard"},
[29741] = {id=29741,name="Sekhemi the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5034,mapID=249,starts={{npcID=55210,x=0.316,y=0.63,mapID=249}},ends={{npcID=55210,x=0.316,y=0.63,mapID=249}},coords={x=0.316,y=0.63,source="quest_giver",mapID=249},questType="standard"},
[29742] = {id=29742,name="Menkhaf the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5034,mapID=249,starts={{npcID=55211,x=0.654,y=0.186,mapID=249}},ends={{npcID=55211,x=0.654,y=0.186,mapID=249}},coords={x=0.654,y=0.186,source="quest_giver",mapID=249},questType="standard"},
[29744] = {id=29744,name="Some \"Pupil of Nature\"",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="Wood sprites are not prone to wandering, so I'm surprised they ventured down as far as the mason's quarter. Something must be forcing them out of their natural habitat. These particular sprites are native to the Woods of the Lost, just north of here. I'd go myself, but I've heard those woods are haunted. So yeah, that's out. I guess we'll never know. Orrrr... A big brave adventurer like YOU could go check it out! What do you say?",questType="standard"},
[29766] = {id=29766,name="A Good Start",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="Regardless of our predicament, our orders stand. We are to learn the lay of this land and prepare it for Hellscream's fleet. But first, we must deal with these savages! You see these corpses I've stacked up around the camp? I want mountains of them! We are the Horde! These vermin have not learned to fear us yet, but we will fix that soon enough...",questType="standard"},
[29767] = {id=29767,name="Fish Fry",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=5785,mapID=371,description="Fortune favors the bold! Your calculated aggressive actions have yielded unexpected rewards. If you can slay these fishcatchers after a successful haul, you'll inherit their slippery spoils. Thinning out the enemy while feeding your allies - the picture of efficiency!",questType="standard"},
[29809] = {id=29809,name="Efficient Excavations",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=5034,mapID=249,description="This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects. After a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here. A map on the back cover indicates that the author has a bunker in the southwest region of Uldum . Perhaps an introduction is in order.",questType="standard"},
[29820] = {id=29820,name="Into the Nexus",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=4120,description="I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days. Would you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.",questType="dungeon"},
[29831] = {id=29831,name="DEPRECATED: Terror on the High Seas",level=5,requiredLevel=5,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="Word has reached Stormwind of terrible crimes committed against ships carrying Alliance citizens. The Horde stands accused of stopping Alliance ships, boarding them, mistreating passengers, and stealing cargo. Heroes of the Alliance, your help is needed to determine the truth of these allegations! Seek out Grand Admiral Jes-Tereth at Stormwind Keep if you would answer the call.",questType="standard"},
[29832] = {id=29832,name="DEPRECATED: Gathering Evidence",level=5,requiredLevel=5,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="A ship called the Bravery routinely ferries passengers and cargo from Stormwind port to Rut'theran Village, right outside Darnassus. Well, the ship has just returned with distressing news. Both passengers and crew say that Horde vessels stopped and boarded the Bravery in the waters off Teldrassil, mistreated those on board, and stole some of the cargo before turning the ship around. We have to find out what happened, . Would you go to Stormwind Harbor and listen to the stories of the passengers?",questType="standard"},
[29837] = {id=29837,name="Sacred Scroll",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="The unfamiliar markings on this parchment have an elegance about them that Yoggtord and his gang don't seem capable of. You suspect that, like everything else these Hozu possess, this is stolen merchandise. Perhaps the original owner of the scroll is still nearby...",questType="standard"},
[29838] = {id=29838,name="One of a Kind",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="At first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'. If what I learned be true, den dey have a special golem - one like nuthin' created before! Bring me back a piece from dat golem ta study.",questType="dungeon"},
[29839] = {id=29839,name="One of a Kind",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="Dis whole mess coulda been avoided if da Drakkari had worshipped da gods instead of destroyin' dem. I heard dat dey have a special golem - one imbued with forbidden powah. Bring me back a piece from dat golem so we can learn from our bruddas and sistahs.",questType="dungeon"},
[29842] = {id=29842,name="Seeking Answers",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="So much to ponder, traveler... You first must learn how to ask before your mind can discern the truth. I have completed my meditations for today, but my candles remain at the Cairn of Blood. Go there. Clear your mind. We will speak again when you are prepared to hear my words.",questType="standard"},
[29854] = {id=29854,name="DEPRECATED: Claiming Kalimdor",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=1637,mapID=85,description="Victory shall soon be ours! Our forces have engaged the enemy all over Kalimdor. Warchief Garrosh Hellscream has commanded all able-bodied s to report for duty in support of our latest offensive. Make your way to Grommash Hold in Orgrimmar and present yourself to General Nazgrim for immediate assignment! For the Horde!",questType="standard"},
[29857] = {id=29857,name="DEPRECATED: Where Are Those Ships?",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=1637,mapID=85,description="With most of our fleet leading the attack on Theramore and engaging the enemy elsewhere, we're going to need more ships to complete our blockade of Kalimdor. The warchief ordered the shipwrights at Zoram'gar Outpost in Ashenvale to work overtime to meet the demand, but none of the new craft have arrived yet. Travel there and put the question to their overseer. Tell them the warchief wants his ships!",questType="standard"},
[29867] = {id=29867,name="DEPRECATED: Shadow Hunter Urko'jin",level=5,requiredLevel=5,faction="none",expansion=4,description="We need to fill the remaining slots in the new blockade fleet before the night elves can reestablish their spy network in the city. The Darkspears have yet to contribute much to the war effort, but if we can convince Shadow Hunter Urko'jin to add his forces to the fleet, that will change. Problem is, Urko'jin won't go to war without the blessing of the spirits. Pay a visit to Darkspear Hold in the Echo Isles, retrieve the totem of seafaring, and deliver it to Urko'jin in the Valley of Spirits.",questType="standard"},
[29886] = {id=29886,name="Zen Healing",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure. Luckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries. The flowers growing on the surface of Glass Lake are needed to make the antidote. , go quickly and bring back some blooms. Your Admiral's life depends on it.",questType="standard"},
[29895] = {id=29895,name="Trail of the White Pawn",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Although the cloak is ragged and torn, there is no mistaking the fine tailoring and the King's royal crest. You should show it to your Alliance commander.",ends={{npcID=60970,x=0.588,y=0.816,mapID=371}},questType="standard"},
[29938] = {id=29938,name="Friends and Foes",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="These ookin' Jinyu grookin Kah Kah's nephews! Wikket once kill many hozen. Now wikket kill many jinyu.",questType="standard"},
[29999] = {id=29999,name="The Rider's Bind",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Have you seen the young serpents in the training yard? The littles ones tend to be mischievous, and some of them ran off to play before the training session. The Mistress will get angry if she discovers they're missing. Would you go find them and bring them back to me? I don't want them to get into trouble. They like to play out in the open, so look for them in courtyards and around the spires.",starts={{npcID=56784,x=0.58,y=0.59,mapID=371}},ends={{npcID=56784,x=0.58,y=0.59,mapID=371}},coords={x=0.58,y=0.59,source="quest_giver",mapID=371},questType="standard"},
[30000] = {id=30000,name="The Jade Serpent",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="You came to deliver a message to the Jade Serpent, right? I guess it's time you met her.",starts={{npcID=56784,x=0.58,y=0.59,mapID=371}},ends={{npcID=57242,x=0.558,y=0.57,mapID=371}},coords={x=0.58,y=0.59,source="quest_giver",mapID=371},questType="standard"},
[30003] = {id=30003,name="A Book By Its Cover",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[30031] = {id=30031,name="Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="As long as you're here, you might as well help me out. I'm feeling pretty darn unqualified for the task, seeing as I've never drank a drop of beer in my life. You should try a little sample of each of their grains. Let's see if any of this stuff is sweet enough for Uncle Chen.",starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56138,x=0.688,y=0.432,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30047] = {id=30047,name="The Chen Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Uncle Chen is going to love this. Or... he might tell us to find something sweeter. He's kind of dumb like that. Let's get this grain back to him at Halfhill.",starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56133,x=0.86,y=0.22,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30048] = {id=30048,name="Li Li and the Grain",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I'll let you in on my brewing plan, : I'm planning on making an Emperor Stout. Done right, it should be dark, roasty, and high in alcohol. I just realized... I never told my plans to Li Li . She'll have no idea what type of grain to bring back! Could you speak with her? I need her to bring back the sweetest malted grains she can find.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=56138,x=0.688,y=0.432,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30049] = {id=30049,name="Doesn't Hold Water",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Would you mind checking in on Mudmug ? He may need some assistance bringing that water back. I'm sure he'll appreciate the help of a big, strong like yourself to help him shoulder the load.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=56474,x=0.686,y=0.432,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30053] = {id=30053,name="Hop Hunting",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="With Li Li fetching grain, and Mudmug handling our water, all we need is hops, and some good wood barrels. I'll handle the barrels... but I need you to gather the hops. I don't know much about the hops from this land, but I'm sure the nearby farmers have something worth brewing with. Go see what you can rustle up.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=57385,x=0.386,y=0.516,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30055] = {id=30055,name="Stormstout's Hops",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="All three farmers have delivered their hops to Halfhill. Perhaps you should check in with Chen to make sure that he received them.",ends={{npcID=56133,x=0.86,y=0.22,mapID=376}},questType="standard"},
[30075] = {id=30075,name="Clear the Way",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Are you seeing this? Virmen, hozen, and water sprites... all pouring out of the brewery doors and windows! What the heck is going on in there!? There is another entrance, on the eastern side of the brewery. I'm going to run over there and try to figure out what's going on. In the meantime, see if you can't get rid of these creatures. There's nothing worse than a drunken hozen.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=56133,x=0.86,y=0.22,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30076] = {id=30076,name="The Fanciest Water",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I've heard lots of cockamamie rumors about this here brewery. I thought they were all false... until I saw that giant hozen. So, it got me thinkin', what if the other rumors are true? I heard this one rumor just the other day about some water sprites that run around inside the brewery, causin' a ruckus and whatnot. Their bodies are actually MADE OF WATER. I reckon a man could make some mighty fine beer with some fancy water like that. If you find any, could you bring me some?",starts={{npcID=56474,x=0.686,y=0.432,mapID=376}},ends={{npcID=56474,x=0.686,y=0.432,mapID=376}},coords={x=0.686,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30077] = {id=30077,name="Barrels, Man",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I can't believe that giant hozen! He's just throwing barrels everywhere! Barrels, man! It looks like he managed to get pretty much all the pandaren that were working out in front of the brewery. If I were you, I'd help some of them break out. Put some of those ridiculous muscles to use. We're headed over to the brewery's rear entrance, to the east. Meet you there!",starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56138,x=0.688,y=0.432,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30079] = {id=30079,name="What's Eating Zhu's Watch?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Pandaren always welcome travelers with open arms - and open kegs! But this town full of jerks! Everyone so busy sulking, they won't talk to Ken-Ken at all! Can you find someone in town who will talk to us? Maybe normal pandaren just hiding in the houses?",starts={{npcID=56115,x=0.762,y=0.07,mapID=418}},ends={{npcID=56115,x=0.762,y=0.07,mapID=418}},coords={x=0.762,y=0.07,source="quest_giver",mapID=418},questType="standard"},
[30081] = {id=30081,name="Materia Medica",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Alright, Ken-Ken pretty sure he knows what wrong with pandaren! Got old, old hozen remedy that do the trick. Need to mix honey, fish oil, and salt. Ken-Ken saw lots of beehives in the trees around town, and there must be fish left in the dry ponds. That just leave salt... Mei might know where we can find some.",starts={{npcID=56115,x=0.762,y=0.07,mapID=418}},ends={{npcID=56115,x=0.762,y=0.07,mapID=418}},coords={x=0.762,y=0.07,source="quest_giver",mapID=418},questType="standard"},
[30087] = {id=30087,name="FLAG - Kung Fu Intro",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",questType="standard"},
[30110] = {id=30110,name="LFGDungeons - Cataclysm - Raid Finder - 1st",level=35,requiredLevel=35,faction="none",expansion=4,questType="standard"},
[30119] = {id=30119,name="Well of Eternity RP Tracker",level=5,requiredLevel=5,faction="both",expansion=4,zoneID=5788,description="I am duty-bound to look into your claims immediately, , which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the world tree's branch.",questType="raid"},
[30122] = {id=30122,name="Silver Filigree Flask",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=6757,mapID=554,description="You have found a beautiful silver flask decorated with ornate filigree. With the right materials and your skill in alchemy, it could become quite magical.",questType="standard"},
[30131] = {id=30131,name="Life",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="My child is coming. I must help as I may. Stay nearby, hero. If my wife and child survive, I would have them look on the face of the one who saved them.",starts={{npcID=58113,x=0.604,y=0.254,mapID=418}},ends={{npcID=58113,x=0.604,y=0.254,mapID=418}},coords={x=0.604,y=0.254,source="quest_giver",mapID=418},questType="standard"},
[30137] = {id=30137,name="Egg Collection",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Ahhh, I should have known! You have the look of a hungry initiate. I would gladly help you choose a serpent egg , but the Slitherscale have thoroughly raided the cloud serpent nests. I'm terribly sorry. I don't know what to tell you. Unless you're crazy enough to sneak into the saurok camp to the east and retrieve some stolen cloud serpent eggs , I'm afraid I can't help you.",starts={{npcID=58225,x=0.654,y=0.316,mapID=371}},ends={{npcID=58225,x=0.654,y=0.316,mapID=371}},coords={x=0.654,y=0.316,source="quest_giver",mapID=371},questType="standard"},
[30141] = {id=30141,name="The Rider's Journey",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Excellent, just excellent! I will return the other eggs to their nests, undisturbed. In the meantime, deliver your egg to Instructor Skythorn at The Arboretum.",starts={{npcID=58225,x=0.654,y=0.316,mapID=371}},ends={{npcID=58228,x=0.574,y=0.45,mapID=371}},coords={x=0.654,y=0.316,source="quest_giver",mapID=371},questType="standard"},
[30142] = {id=30142,name="It's A...",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Oh my! This egg is going to hatch at any second! Well, looks like this little guy is eager to meet you. Are you ready?",starts={{npcID=58228,x=0.574,y=0.45,mapID=371}},ends={{npcID=58228,x=0.574,y=0.45,mapID=371}},coords={x=0.574,y=0.45,source="quest_giver",mapID=371},questType="standard"},
[30149] = {id=30149,name="A Feast for the Senses",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="I have heard that you know a thing or two about cooking. As it so happens, serpents love to eat Fish Cakes . If you use your culinary skills and bring me 5 of these dishes, the cloud serpents around here will be very happy.",starts={{npcID=58413,x=0.574,y=0.446,mapID=371}},ends={{npcID=58413,x=0.574,y=0.446,mapID=371}},coords={x=0.574,y=0.446,source="quest_giver",mapID=371},questType="standard"},
[30177] = {id=30177,name="Daily Heroic Random (1st) (Cataclysm)",level=5,requiredLevel=5,faction="both",expansion=4,questType="standard"},
[30179] = {id=30179,name="Poisoned!",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="The... mogu. Do not trust. Poison. Get sample... sample blades. Bring to Dezco... in Thunder Cleft, west of here.",starts={{npcID=58160,x=0.688,y=0.222,mapID=418}},ends={{npcID=58113,x=0.604,y=0.254,mapID=418}},coords={x=0.688,y=0.222,source="quest_giver",mapID=418},questType="standard"},
[30197] = {id=30197,name="Cart Ride",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,description="The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.",questType="standard"},
[30198] = {id=30198,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30199] = {id=30199,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
