[30202] = {id=30202,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30203] = {id=30203,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30209] = {id=30209,name="Tracking Event: 3rd Place",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5974,questType="standard"},
[30230] = {id=30230,name="Re-Reclaim",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Mogu are thugs. They have always been thugs. Only when they ruled their empires in the old stories did they ever know any kind of magic. But these mogu are using arcane portals and spells. We need to stop them! $p, look for any artifacts the mogu are using to cast their magics with. I saw a number of their collectors and reclaimers to the west and north that were gathering these items.",starts={{npcID=56112,x=0.6,y=0.25,mapID=418}},ends={{npcID=56112,x=0.6,y=0.25,mapID=418}},coords={x=0.6,y=0.25,source="quest_giver",mapID=418},questType="standard"},
[30241] = {id=30241,name="Warn Stoneplow",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,mapID=376,description="So much death. And more to come, if Ambassador Han's stories of the mantid are to be believed. We must help. We must do our part to save lives. Travel to Stoneplow. Warn them of the coming mantid attack. I will join you with what forces I can muster once I have laid Kor's body to rest.",starts={{npcID=58607,x=0.288,y=0.508,mapID=418}},ends={{npcID=56720,x=0.194,y=0.568,mapID=376}},coords={x=0.288,y=0.508,source="quest_giver",mapID=376},questType="standard"},
[30247] = {id=30247,name="Roll Club: Vale of Eternal Blossoms",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,description="Follow the flags. Make the checkpoints. Round the loop. Get back to me before your time is up. Speak to me when you're ready to roll.",questType="standard"},
[30262] = {id=30262,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30268] = {id=30268,name="The Murksweats",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Take a good look. The river nearby is swarming with these snakes. Their venom causes a condition the locals call \"the murksweats.\" Several refugees were bitten as they fled the temple and have already begun to show symptoms: nausea, vomiting, and intense sweating as the body rejects all fluids, causing dehydration and potentially death. We are administering anti-venom as quickly as possible, but we'll need more venom glands. Don't bother removing the glands yourself - just bring back the whole head.",starts={{npcID=58609,x=0.404,y=0.346,mapID=418}},ends={{npcID=58609,x=0.404,y=0.346,mapID=418}},coords={x=0.404,y=0.346,source="quest_giver",mapID=418},questType="standard"},
[30303] = {id=30303,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30306] = {id=30306,name="The Battle Ring",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,mapID=1530,description="We have some fresh trainees that are far from being a danger to you, but in numbers, they may prove enough of a challenge. And if not, they could use the lesson in humility. Step into the battle ring when you're ready. Don't go easy on them.",starts={{npcID=58962,x=0.204,y=0.736,mapID=1530}},ends={{npcID=58962,x=0.204,y=0.736,mapID=1530}},coords={x=0.204,y=0.736,source="quest_giver",mapID=1530},questType="standard"},
[30311] = {id=30311,name="High Standards",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,description="If I had to pick the most important quality for a battle standard, it would be that it's standing up... and not on fire, but mostly the first one. So needless to say, I'm a bit concerned about our standard situation at the moment. If some unknown were to be so kind as to take a walk out on the battlefield to our northwest and stand our standards back up, both myself and my extremely sexy yet somewhat commanding wife would be very grateful.",questType="standard"},
[30343] = {id=30343,name="To the Waterline!",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=6040,questType="dungeon"},
[30344] = {id=30344,name="The Lost Dynasty",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="I wonder if I could bother you for another task. My daughter, the good Sentinel Commander Lyalia here, refuses to let me go into the field. I have spent everyday in that oubliette staring at the ruins to our north, itching to investigate. If we are where I suspect we are those ruins could contain the key we need to finding the fabled Pools of Youth! Please, ! Go to those ruins and salvage any tablets that still have writing on them.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30346] = {id=30346,name="Where are the Pools",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Perhaps these mogu know where the pools are. Our scouts have reported seeing a commander along the southern side of the Ruins of Dojan. Kill him and take whatever information he is carrying. They should lead you to the pool.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30347] = {id=30347,name="The Pools of Youth",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="North! Go north to the Pools of Youth. Get some of the water but be on your guard. The mogu list this as a \"high value\" target. Kang Bramblestaff will meet you there if he has not already arrived by your side.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30348] = {id=30348,name="Immortality?",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Something is... off. The water feels strange. When we arrived here I felt the presence of the Light, strong and vibrant, far to the north. I thought it would be the Pools of Youth. But this... this water is tainted somehow. Stained with mogu magics. I think it best I try only a sip and we see what happens.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30350] = {id=30350,name="Squirmy Delight",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,description="The hidden master may have to wait. Look at these people, $p. They are so THIN! They must be starving. You know what we need? A big steaming bowl of Squirmy Delight . If you find yourself near a river, try rounding up some intact skitterer glands and I'll cook up a batch.",starts={{npcID=56114,x=0.674,y=0.326,mapID=418}},ends={{npcID=56114,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=376},questType="standard"},
[30351] = {id=30351,name="Lotus Tea",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="The mogu really like their poisons and curses. Mama Bramblestaff always said lotus tea cures any mogu curse. I saw some imperial lotus plants in the nearby Ruins of Dojan. We should go gather some of their leaves and keep them on hand just in case the mogu get unruly. Also, this will give me a chance to introduce my fists to some mogu faces.",starts={{npcID=56114,x=0.674,y=0.326,mapID=418}},ends={{npcID=56114,x=0.674,y=0.326,mapID=418},{npcID=58814,x=0.548,y=0.382,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30353] = {id=30353,name="Profit Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Two words: Tiger Blood! This is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff. And this jungle is just full of tigers. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.",starts={{npcID=58779,x=0.676,y=0.256,mapID=418}},ends={{npcID=58779,x=0.676,y=0.256,mapID=418}},coords={x=0.676,y=0.256,source="quest_giver",mapID=418},questType="standard"},
[30354] = {id=30354,name="No Sister Left Behind",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="We were searching the ruins south of here when the mogu fell upon us out of nowhere. Some of us were able to retreat to this encampment but many others were captured. The mogu have also caught a number of the Horde who happened to be in the area as well. Please, $p, rescue any sentinels that you can. Leave the Dawnchasers to their fate.",starts={{npcID=58821,x=0.248,y=0.34,mapID=418}},ends={{npcID=58821,x=0.248,y=0.34,mapID=418}},coords={x=0.248,y=0.34,source="quest_giver",mapID=418},questType="standard"},
[30355] = {id=30355,name="Re-Reclaim",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Mogu do NOT use arcane magics. They are thugs. They have always been thugs. Only when they ruled their empires in the old stories did they ever know any kind of magic. But these mogu are using arcane portals and old artifacts. We need to stop them! $p, look for any artifacts the mogu are using to cast their magics with. I saw piles of these items being collected near the Ruins of Korja south of here.",starts={{npcID=56114,x=0.674,y=0.326,mapID=418}},ends={{npcID=56114,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30358] = {id=30358,name="Gryphon, Down",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
[30359] = {id=30359,name="The Lord Reclaimer",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="They have my daughter! Brojai... that Lord Reclaimer! I can see him clearly through Lyalia's eyes. That foolish girl must have tried to take him head on. Please, $p! Go to the Ruins of Korja and try to free her. I'll get Kang and try to draw out Brojai from the ruins with a distraction.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30360] = {id=30360,name="Warn Stoneplow",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,description="My father gave me his life. Tyrande gave me her trust. My sentinels gave me their allegiance. It is time I repaid them all. With Brojai dead we can mop up the remaining mogu. The next threat is the mantid. Go north to Stoneplow and lend them your help. Tell them I will be bringing what sentinels I can muster to aid in the defense of their city against the mantid.",starts={{npcID=58821,x=0.248,y=0.34,mapID=418}},ends={{npcID=56720,x=0.194,y=0.568,mapID=376}},coords={x=0.248,y=0.34,source="quest_giver",mapID=376},questType="standard"},
[30361] = {id=30361,name="The Mantid",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,description="The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that. Now they are preparing to hit Stoneplow. Please, , destroy some of these beasts before they get sufficient numbers to flank our home. If my cousin, Ambassador Len , is still alive and at our convoy he should be able to reward you for your help.",starts={{npcID=58630,x=0.248,y=0.342,mapID=418}},ends={{npcID=58954,x=0.156,y=0.396,mapID=418}},coords={x=0.248,y=0.342,source="quest_giver",mapID=376},questType="standard"},
[30362] = {id=30362,name="Tanks for Nothing!",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
[30364] = {id=30364,name="Fly, Spy!",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
