[30426] = {id=30426,name="A Marsh Lily for Fish",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=58705,x=0.528,y=0.518,mapID=376}},ends={{npcID=58705,x=0.528,y=0.518,mapID=376}},coords={x=0.528,y=0.518,source="quest_giver",mapID=376},questType="standard"},
[30431] = {id=30431,name="A Blue Feather for Tina",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=58761,x=0.45,y=0.338,mapID=376}},ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},coords={x=0.45,y=0.338,source="quest_giver",mapID=376},questType="standard"},
[30432] = {id=30432,name="A Marsh Lily for Tina",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=58761,x=0.45,y=0.338,mapID=376}},ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},coords={x=0.45,y=0.338,source="quest_giver",mapID=376},questType="standard"},
[30451] = {id=30451,name="Darkmoon Serpent Deck",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,mapID=407,description="Now that you have gathered all of the Serpent cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",ends={{npcID=14847,x=0.518,y=0.606,mapID=407}},questType="standard"},
[30458] = {id=30458,name="The Scouts Return",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description=", your friends have returned from their scouting mission. They need to see you immediately. I'm afraid... Well, I'd better say no more. You will see for yourself.",questType="standard"},
[30459] = {id=30459,name="All of the Arrows",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="As soon as their reinforcements arrive, the yaungol are going to overrun our position here. If they do that, the village will be lost. Would you be willing to retrieve as many arrows off the battlefield as you can carry? I have a plan that just might save us with your help.",starts={{npcID=59076,x=0.708,y=0.904,mapID=379}},ends={{npcID=59076,x=0.708,y=0.904,mapID=379}},coords={x=0.708,y=0.904,source="quest_giver",mapID=379},questType="standard"},
[30464] = {id=30464,name="Going West",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Leza now walks with the ancestors of this strange land. I must look now to the living. Kor has led a group of our scouts west deeper into the jungle. Track him down and lend what aid you can to him. We will join you as quickly as we are able.",starts={{npcID=58113,x=0.604,y=0.254,mapID=418}},ends={{npcID=58114,x=0.598,y=0.248,mapID=418}},coords={x=0.604,y=0.254,source="quest_giver",mapID=418},questType="standard"},
[30466] = {id=30466,name="Sufficient Motivation",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Training these savages has been quite a task, . Finding ways to motivate them was easy enough; the problem is keeping them motivated.. and focused... and awake. Now that you're back, you can help me in getting the less disciplined Hozen moving, if you catch my drift. I'll leave the method up to you.",starts={{npcID=57108,x=0.28,y=0.47,mapID=371}},ends={{npcID=57108,x=0.28,y=0.47,mapID=371}},coords={x=0.28,y=0.47,source="quest_giver",mapID=371},questType="standard"},
[30467] = {id=30467,name="My Son...",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="My son - can you find my son? When the Jinyu attacked, he ran off in the confusion. I don't know if they've done anything with him, or if he's still alive, even. Nothing else matters if I can't find him. I'd ask Mei... but something's wrong with her. She seems too... impulsive since the attack. I just can't trust that she'd bring him back safely.",starts={{npcID=59263,x=0.748,y=0.888,mapID=379}},ends={{npcID=59272,x=0.746,y=0.768,mapID=379}},coords={x=0.748,y=0.888,source="quest_giver",mapID=379},questType="standard"},
[30470] = {id=30470,name="A Gift For Tina",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="That Tina Mudclaw is in the Halfhill Market today, visiting her sister. She's really nice, but she's really hard to get gifts for! There's a little jewel that can be found in the cliffs to the north. It's called a chrysoberyl, and it changes color when you hold it. I'll bet she doesn't have one of THOSE! Look inside the virmen caves. I bet you'll find one really fast.",starts={{npcID=64464,x=0.526,y=0.504,mapID=376}},ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},coords={x=0.526,y=0.504,source="quest_giver",mapID=376},questType="standard"},
[30483] = {id=30483,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30490] = {id=30490,name="Yakity Yak",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Yaungols! They come through here taking what they want and destroying whatever's left. I can't have these thugs destroy the last pieces of the Yak Wash here. It's all my boy and I have left. Head over to our old ranch and dish out some pain on them yaungols. I bet if you kill enough of them they'll think twice before attacking anything in this area.",questType="standard"},
[30514] = {id=30514,name="Challenge Accepted",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="The yaungol have always been a difficult, proud people, but never this violent or aggressive. I do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar , leader of the Bataari yaungol, lives. Go, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.",starts={{npcID=63542,x=0.546,y=0.842,mapID=379}},ends={{npcID=63542,x=0.546,y=0.842,mapID=379}},coords={x=0.546,y=0.842,source="quest_giver",mapID=379},questType="standard"},
[30515] = {id=30515,name="Challenge Accepted",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="The yaungol have always been a difficult, proud people, but never this violent or aggressive. I do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar , leader of the Bataari yaungol, lives. Go, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.",starts={{npcID=63535,x=0.624,y=0.796,mapID=379}},ends={{npcID=63535,x=0.624,y=0.796,mapID=379}},coords={x=0.624,y=0.796,source="quest_giver",mapID=379},questType="standard"},
[30516] = {id=30516,name="Growing the Farm I: A Little Problem",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="So you need to whack some wily weeds? No problem, neighbor! Only thing is, I'm running low on weed killer. I make my own concoction - very potent, totally organic and good for the earth. Plants love it! Well... except for those pesky weeds. They hate the stuff! If you bring me some Spideroot from the terraces just west of us, I'll make a fresh batch and go down to Yoon's farm myself. I would gather some myself but... well... I hate spiders. You'll see what I mean.",starts={{npcID=57385,x=0.386,y=0.516,mapID=376}},ends={{npcID=57385,x=0.386,y=0.516,mapID=376}},coords={x=0.386,y=0.516,source="quest_giver",mapID=376},questType="standard"},
[30522] = {id=30522,name="Haohan's Vote II: The Real Culprits",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="What are YOU doing here, citypaw? Look, I've got my hands full with a break-in at my shed to the west. Some rascals came in the middle of the night and ransacked the place. I've got missing seeds, broken tools, and eaten inventory to deal with. I'll just add it to my list of other troubles: a whole wagon of melons stolen, a broken water pump, animals ruining my harvest... I wish that I could just get to the bottom of all this already!",starts={{npcID=57402,x=0.446,y=0.34,mapID=376}},ends={{npcID=58646,x=0.522,y=0.488,mapID=376}},coords={x=0.446,y=0.34,source="quest_giver",mapID=376},questType="standard"},
[30527] = {id=30527,name="Haohan's Vote IV: Melons For Felons",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="All right, now I happen to know that those mountain hozen love a delicious, sweet melon. Mr. Haohan's last harvest of melons got stolen, so we're going to have to grow some of our own. Once we have our harvest, we'll use them to lure the nasty hozen's leader out of its cave!",starts={{npcID=58646,x=0.522,y=0.488,mapID=376}},ends={{npcID=58646,x=0.522,y=0.488,mapID=376}},coords={x=0.522,y=0.488,source="quest_giver",mapID=376},questType="standard"},
[30529] = {id=30529,name="Growing the Farm III: The Mossy Boulder",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Now that we're officially members of the Tillers Union, Mr. Mudclaw said he'd be happy to help us upturn this big ole' rock in the middle of our field. Once we clear away that stone, I've got something special planned. Run down and give him a holler to let him know that we're ready.",starts={{npcID=58646,x=0.522,y=0.488,mapID=376}},ends={{npcID=57402,x=0.446,y=0.34,mapID=376}},coords={x=0.522,y=0.488,source="quest_giver",mapID=376},questType="standard"},
[30530] = {id=30530,name="Tracking Event: Started First Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30531] = {id=30531,name="Tracking Event: Finished First Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30532] = {id=30532,name="Tracking Event: Started Second Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30533] = {id=30533,name="Tracking Event: Finished Second Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30535] = {id=30535,name="Learn and Grow I: Seeds",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Well, first things first! I'm going to need lots of help 'round here. If we're going to be partners, you've got to learn how to harvest crops, and if you wanna harvest crops you gotta plant seeds! Now it's my understanding that a mister, uh... Grainfell? No, that wasn't it... Greedfill? That doesn't sound right... Greenfield! That's his name! He's the man to see for seeds. Greenfield's got a stall over at Halfhill Market, directly southeast of here - go see him and pick up some vegetable seeds.",starts={{npcID=58646,x=0.522,y=0.488,mapID=376}},ends={{npcID=58646,x=0.522,y=0.488,mapID=376}},coords={x=0.522,y=0.488,source="quest_giver",mapID=376},questType="standard"},
[30536] = {id=30536,name="FLAG - Weed War Training",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",questType="standard"},
[30564] = {id=30564,name="Tracking Event: Talked to Dog at Farm",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30566] = {id=30566,name="FLAG - Pest Problems Training",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",questType="standard"},
[30571] = {id=30571,name="Farmhand Freedom",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Those Ordo yaungol are working my farmhands to death! It just ain't right. Please, , save them before it's too late.",starts={{npcID=59573,x=0.602,y=0.858,mapID=379}},ends={{npcID=59573,x=0.602,y=0.858,mapID=379}},coords={x=0.602,y=0.858,source="quest_giver",mapID=379},questType="standard"},
[30573] = {id=30573,name="Tracking Event: Started Third Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30574] = {id=30574,name="Tracking Event: Finished Third Expansion",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[30575] = {id=30575,name="Round 'Em Up",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="Mobility is going to be key to maintaining our foothold in this new land. Problem is, there's no way to maintain mobility without mounts, and... well, we don't have many of those here, now do we? The local yaks seem to make good mounts. At least, the local pandaren say they do. Why don't you go round some up for us?",starts={{npcID=59441,x=0.716,y=0.93,mapID=379}},ends={{npcID=59441,x=0.716,y=0.93,mapID=379}},coords={x=0.716,y=0.93,source="quest_giver",mapID=379},questType="standard"},
[30588] = {id=30588,name="Fishing for a Bruising",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="The riverblade saurok clan is attacking one of our local fishing expeditions! They need help right away! Thin those saurok out and help that expedition return safely!",starts={{npcID=59586,x=0.676,y=0.436,mapID=418}},ends={{npcID=59586,x=0.676,y=0.436,mapID=418}},coords={x=0.676,y=0.436,source="quest_giver",mapID=418},questType="standard"},
[30595] = {id=30595,name="Profiting off of the Past",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6134,mapID=418,description="Let me guess, you're here to deal with the mogu statues that are being reanimated. What a coincidence, I'm here to, um... conduct research on the mogu. I tell you what, if you bring me as many of the mogu relics in there that you can carry, I'll give you a cut. Of the research... funding.",starts={{npcID=59821,x=0.596,y=0.782,mapID=379}},ends={{npcID=59821,x=0.596,y=0.782,mapID=379}},coords={x=0.596,y=0.782,source="quest_giver",mapID=418},questType="standard"},
[30596] = {id=30596,name="A Zandalari Troll?",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you. It's clear that the threat to Westerly Rest will not end until he's been dealt with.",questType="standard"},
[30597] = {id=30597,name="Strange Spherical Stone",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=6757,mapID=554,description="This beautiful stone clearly has magical potential... at least to one trained in alchemy. You are certain that with the right herbs native to Pandaria, this stone could become very useful.",questType="standard"},
[30615] = {id=30615,name="A Zandalari Troll?",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you. It's clear that the threat to Westerly Rest will not end until he's been dealt with.",questType="standard"},
[30629] = {id=30629,name="FLAG - Player Began Finale",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",questType="standard"},
[30656] = {id=30656,name="Barrels of Fun",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="I love blowing stuff up. It's in my blood! The yaungol to the west at Fire Camp Ordo have a ton of explosive barrels just lying around. I say we put them to good use and destroy their oil-pumpin' machines while having some fun!",starts={{npcID=59448,x=0.628,y=0.798,mapID=379}},ends={{npcID=59448,x=0.628,y=0.798,mapID=379}},coords={x=0.628,y=0.798,source="quest_giver",mapID=379},questType="standard"},
[30657] = {id=30657,name="In Tents Channeling",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,description="The yaungol of Fire Camp Ordo are the worst threat we're facing. I need you to head west and take out their leader. The coward is hiding in a cave, which is protected by a fire shield cast by his four underlings. Take them out and the shield will come down. You'll find them in their tents, channeling.",starts={{npcID=59442,x=0.716,y=0.932,mapID=379}},coords={x=0.716,y=0.932,source="quest_giver",mapID=379},questType="standard"},
[30658] = {id=30658,name="Huff & Puff",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Have you heard of the prickly puffer fish ? Of course you haven't, you're new around these parts! They can be found in the sarjun depths, due west of here. Take this fishing spear and see if you can bring me back of few of their poison tipped spines.",starts={{npcID=60135,x=0.676,y=0.424,mapID=418}},ends={{npcID=60135,x=0.676,y=0.424,mapID=418}},coords={x=0.676,y=0.424,source="quest_giver",mapID=418},questType="standard"},
[30660] = {id=30660,name="The Ordo Warbringer",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,mapID=379,ends={{npcID=59441,x=0.716,y=0.93,mapID=379}},questType="standard"},
[30661] = {id=30661,name="The Ordo Warbringer",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,mapID=379,ends={{npcID=59442,x=0.716,y=0.932,mapID=379}},questType="standard"},
[30666] = {id=30666,name="Sudden, Unexpected Crocolisk Aggression",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Normally, my day consists of catching fish, and then eating the fish I caught, followed by sleeping. Note that I did not include \"fight with a crocolisk\" in that list of activities. You look like a handy . Can you go get rid of some of these crocolisks, so I can get back to my regular routine? The crocolisks normally keep to themselves up at Kea Krak, to the northwest.",starts={{npcID=60173,x=0.516,y=0.768,mapID=418}},ends={{npcID=60173,x=0.516,y=0.768,mapID=418}},coords={x=0.516,y=0.768,source="quest_giver",mapID=418},questType="standard"},
[30668] = {id=30668,name="Build Your Own Raft",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Hmm. They don't seem to be... calming down. We're going to have to try something different. You'll need a raft. Go grab some wood planks and seaweed, and bring them over to me. I'll put something together for you.",starts={{npcID=60173,x=0.516,y=0.768,mapID=418}},ends={{npcID=60173,x=0.516,y=0.768,mapID=418}},coords={x=0.516,y=0.768,source="quest_giver",mapID=418},questType="standard"},
[30669] = {id=30669,name="The Lorewalker on the Lake",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Your raft is down in the water below. Take it out to the middle of the lake, where you should find a woman. Her name is Ana Wu. Whenever I have a question that I can't figure out on my own, I'll ask her. She should be able to tell us why these crocolisks won't stop attacking.",starts={{npcID=60173,x=0.516,y=0.768,mapID=418}},ends={{npcID=60139,x=0.46,y=0.788,mapID=418}},coords={x=0.516,y=0.768,source="quest_giver",mapID=418},questType="standard"},
[30670] = {id=30670,name="Turnabout",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Our true enemies are the sha, not the yaungol. The sha are emotion manifest. Destructive, yes. But undisciplined. Undisciplined force cannot last. The flood, in dispersion, loses its force. The wildfire burns its fuel. And, discipline and wisdom can turn their destructive energy against themselves. Bring me the essences of the sha in the village, and I will explain further.",starts={{npcID=60161,x=0.444,y=0.898,mapID=379}},ends={{npcID=60161,x=0.444,y=0.898,mapID=379}},coords={x=0.444,y=0.898,source="quest_giver",mapID=379},questType="standard"},
[30673] = {id=30673,name="Holed Up",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Thank the heavenly spirits for you, ! I don't know how much longer I could've lasted. There are other Firebough Nook survivors, I'm sure of it. Will you help rescue them and get us to the safety of Shado-Pan Fallback?",questType="standard"},
[30677] = {id=30677,name="Shuttle Service",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30680] = {id=30680,name="Holed Up",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Oh thank you, thank you, thank you. If you hadn't come along... Wait! There must be other survivors in the Nook like me! Please, , I beg you. Rescue the rest of my citizens and deliver us safely to Shado-Pan Fallback.",questType="standard"},
[30681] = {id=30681,name="Holed Up",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description="Oh, thank you! There's no way I could have made it back on my own. Come to think of it, there must be others around Firebough Nook that need to be rescued. Shall we go collect them and then head to the safety of Shado-Pan Fallback?",questType="standard"},
[30710] = {id=30710,name="Provoking the Trolls",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5841,mapID=379,description="We've managed to push them back this far, but I doubt that we will remain safe for long if we do not deal with them once and for all. My husband, coward or fool that he is, does not wish to provoke them. I will not be cowed so. We will do just that. Slay their forward scouts. Perhaps we can provoke - and then defeat - their leader.",questType="standard"},
[30714] = {id=30714,name="Destroy the Leaders",level=1,requiredLevel=1,faction="both",expansion=4,description="And, now they fear you. Their leaders, a Blademaster and a Mage, lie deeper in the ruins. Kill them. Make them hurt. For us.",questType="standard"},
[30719] = {id=30719,name="FLAG - Cradle of Chi-Ji Progress Bit 01",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30720] = {id=30720,name="FLAG - Cradle of Chi-Ji Progress Bit 02",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30721] = {id=30721,name="FLAG - Cradle of Chi-Ji Progress Bit 03",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30722] = {id=30722,name="FLAG - Cradle of Chi-Ji Progress Bit 04",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,questType="standard"},
[30744] = {id=30744,name="Kota Blend",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="Kota Peak is famous for its kafa bushes - no other can survive at this elevation. Grummles make very good living selling Kafa'kota Blend, but it's dangerous now thanks to my cousin here. He's got the wildlife up there hooked on kafa with his scheming. Kafa'kota is more scarce than ever with goots gobblin' it up and yetis hoarding it in their caves. I pay you good for any berries you bring down from Kota. Here, take a sample. Eat it. See for yourself the power of kafa.",starts={{npcID=60503,x=0.424,y=0.696,mapID=379}},coords={x=0.424,y=0.696,source="quest_giver",mapID=379},questType="standard"},
[30765] = {id=30765,name="Regaining Honor",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,description=", the yaungol warchief, Humongous, killed Shado-Master Zhen. He has his banner. You have to kill Humongous and regain Zhen's honor! If you don't, I will.",questType="standard"},
[30766] = {id=30766,name="Profiting off of the Past",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,questType="standard"},
[30817] = {id=30817,name="The Healing of Shen-zin Su",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="This is what comes of such recklessness. How could he think this was even a possibility? Nevermind, there's no time for that now. We need to act to save Shen-zin Su. Find any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound. Keep the healers safe at all costs!",questType="standard"},
[30818] = {id=30818,name="A New Fate",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description=", I'm thankful the plan worked, but just barely. We would be sinking to the bottom of the ocean with all of Shen-zin Su if you hadn't been here. I don't think I can ever forgive Ji for this kind of recklessness. There will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.",questType="standard"},
[30910] = {id=30910,name="Greenstone Village",level=1,requiredLevel=1,faction="both",expansion=4,questType="standard"},
[30918] = {id=30918,name="Hui's Vengeance",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6209,questType="standard"},
[30928] = {id=30928,name="A Trail of Fear",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="You now know Niuzao's secret. We are not only the wardens of this temple... we were the wardens of the Sha of Fear that was buried beneath it. The Sha itself may have escaped... but it left traces behind. If you're truly going down into the catacombs, you should eliminate those traces, before they escape and cause greater problems than those we already face.",starts={{npcID=61585,x=0.392,y=0.62,mapID=388}},ends={{npcID=61585,x=0.392,y=0.62,mapID=388}},coords={x=0.392,y=0.62,source="quest_giver",mapID=388},questType="standard"},
[30961] = {id=30961,name="Savior of the Inkgill",level=0,requiredLevel=0,faction="none",expansion=4,questType="standard"},
[30974] = {id=30974,name="Raising Spirits",level=25,requiredLevel=25,faction="none",expansion=4,zoneID=5842,mapID=388,description="The kegs are full of my worst stock. Good for burning, crap for drinking. I've broken out some tankards of my best spirits and had them carried out amongst the kegs though - those are for my well-deserving men! Spirits to raise their spirits after endless, grueling fighting. Would you be up for spreading the good cheer?",questType="standard"},
[30986] = {id=30986,name="Ancient Mogu Crypt",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=6208,questType="dungeon"},
[30990] = {id=30990,name="Open the Golden Doors",level=0,requiredLevel=0,faction="none",expansion=4,zoneID=6208,questType="standard"},
[31000] = {id=31000,name="Dread Space",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,mapID=1530,description="Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled such as yourself. Take a kite and check in with Bowmistress Li .",starts={{npcID=62667,x=0.506,y=0.118,mapID=422}},ends={{npcID=62112,x=0.14,y=0.77,mapID=1530}},coords={x=0.506,y=0.118,source="quest_giver",mapID=1530},questType="standard"},
[31004] = {id=31004,name="Preserved in Amber",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Take... this... Awaken... the Wind-Reaver... It is the only way... to end the swarm.",starts={{npcID=62203,x=0.736,y=0.276,mapID=422}},ends={{npcID=62202,x=0.702,y=0.256,mapID=422}},coords={x=0.736,y=0.276,source="quest_giver",mapID=422},questType="standard"},
[31005] = {id=31005,name="Wakening Sickness",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="You will forgive my current state. I have slept for many years. A Klaxxi'va should have been here to attend my Wakening with kypari sap... but you will have to do. I sense the buzzing of sapflies to the south. They gorge on the nourishing sap I need. Bring them to me.",starts={{npcID=62202,x=0.702,y=0.256,mapID=422}},ends={{npcID=62202,x=0.702,y=0.256,mapID=422}},coords={x=0.702,y=0.256,source="quest_giver",mapID=422},questType="standard"},
[31016] = {id=31016,name="The Lorewalkers",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=5840,mapID=1530,description="Dear $p, We have uncovered something tremendous in the Vale of Eternal Blossoms . A great repository of books, scrolls, and lore that has remained untouched since the days of the mogu empire. Please, join us at your earliest convenience. You can find this Seat of Knowledge by traveling to the infamous Mogu'shan Vaults, and then flying to the landing just above the entrance. I look forward to your arrival! Sincerely, Lorewalker Cho",questType="standard"},
[31027] = {id=31027,name="Defeat the Abomination",level=0,requiredLevel=0,faction="none",expansion=4,zoneID=6208,description="Now that the pool of life is cleansed, the way to the crypt's interior is open. Make your way down there and defeat the abomination.",questType="standard"},
[31034] = {id=31034,name="Enemies Below",level=7,requiredLevel=7,faction="horde",expansion=4,zoneID=2437,description="There are enemies of the Horde beneath this very city, . The Searing Blade plots to take Orgrimmar for their own, and have already taken Ragefire Chasm ! We need to storm their forces and retake what is ours! Go speak with Commander Bagran just inside Ragefire Chasm . He will have further orders for you.",starts={{npcID=3144,x=0.49,y=0.722,mapID=85},{npcID=14720,x=0.486,y=0.71,mapID=85},{npcID=39605,x=0.482,y=0.706,mapID=85},{npcID=86832,x=0.482,y=0.706,mapID=85}},coords={x=0.49,y=0.722,source="quest_giver",zoneID=1637},questType="dungeon"},
[31050] = {id=31050,name="Chose Fire Mage",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31051] = {id=31051,name="Chose Frost Mage",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31052] = {id=31052,name="Chose Priest",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31053] = {id=31053,name="Tracking Event: Started Shado-Pan Dailies",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31054] = {id=31054,name="Unlocked Yalia Sagewhisper",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31076] = {id=31076,name="Fate of the Stormstouts",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Greetings, . I am Chen Stormstout . I'm looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them. Have you seen anyone named Stormstout come through here? Would you mind helping me ask around?",starts={{npcID=62779,x=0.504,y=0.12,mapID=422}},ends={{npcID=62779,x=0.504,y=0.12,mapID=422}},coords={x=0.504,y=0.12,source="quest_giver",mapID=422},questType="standard"},
[31079] = {id=31079,name="The Horror Comes A-Rising",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="We are protected from the mantid. Such was the agreement made so many millennia ago. There are forces from which we are not safe, however. The kyparites beneath the ground to the west will haunt us, chase us... even eat us. The mistlurkers eat our kind by the handful. Help our people, outsider. Defeat our enemies.",starts={{npcID=62772,x=0.382,y=0.172,mapID=422}},ends={{npcID=62772,x=0.382,y=0.172,mapID=422}},coords={x=0.382,y=0.172,source="quest_giver",mapID=422},questType="standard"},
[31081] = {id=31081,name="Incantations Fae and Primal",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I suspect we are going to need the help of these sprites. We have two enchanted daggers, bound together with wood and shade. Now we need someone to perform ancient \"incantations\" on our artifact. Before we ask for favors, let's show the sprites that we mean well. I heard their leader talking about a pair of mistlurkers that kidnapped several of their villagers. If we slay these fog beasts... we may get the \"incantation\" we need in return.",starts={{npcID=62667,x=0.506,y=0.118,mapID=422}},ends={{npcID=62667,x=0.506,y=0.118,mapID=422}},coords={x=0.506,y=0.118,source="quest_giver",mapID=422},questType="standard"},
[31082] = {id=31082,name="Great Vessel of Salvation",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I know what you and the girl-panda seek. We can perform the rite for you... in time. First, I require aid. The seeds fall from our great mother-tree. It is our responsibility to collect them, even in dangerous times like these. Escort my chanters to the motherseeds , that they may bring them back to the collection pit.",starts={{npcID=62771,x=0.386,y=0.172,mapID=422}},ends={{npcID=62771,x=0.386,y=0.172,mapID=422}},coords={x=0.386,y=0.172,source="quest_giver",mapID=422},questType="standard"},
[31096] = {id=31096,name="What is Worth Fighting For",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,mapID=1530,description="Dear $p, You have recovered the story of our people's freedom from the mogu empire. If you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection. Thank you for your diligence! Sincerely, Lorewalker Cho",ends={{npcID=61962,x=0.832,y=0.296,mapID=1530}},questType="standard"},
[31115] = {id=31115,name="FLAG - Freed Han",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6138,mapID=422,questType="standard"},
[31118] = {id=31118,name="The Deadtalker Cipher",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="We need to understand what went wrong with the Deadtalkers. For so many years, the Deadtalkers were simply responsible for maintaining the burial grounds and holding funerals for fallen warriors. From a recent raid, we've recovered a tablet from the grounds that is clearly written using a cipher, but it isn't one we've encountered before. If you can gather a ciphered scroll from one of the Deadtalkers, we can begin to put together the cypher and understand what's happened.",starts={{npcID=63009,x=0.494,y=0.706,mapID=388}},ends={{npcID=63009,x=0.494,y=0.706,mapID=388}},coords={x=0.494,y=0.706,source="quest_giver",mapID=388},questType="standard"},
[31122] = {id=31122,name="Chose Prot Warrior",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31123] = {id=31123,name="Chose Arms Warrior",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31124] = {id=31124,name="Chose Brewmaster",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31125] = {id=31125,name="Unlocked Chao",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31126] = {id=31126,name="Unlocked Lao-Chen",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31129] = {id=31129,name="Fate of the Stormstouts",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="$p! It is so great to see you healthy, and traveling so far. It would seem that our paths are quite tightly intertwined. I'm here looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them. Have you seen anyone named Stormstout come through here? Would you mind helping me ask around?",starts={{npcID=62779,x=0.504,y=0.12,mapID=422}},ends={{npcID=62779,x=0.504,y=0.12,mapID=422}},coords={x=0.504,y=0.12,source="quest_giver",mapID=422},questType="standard"},
[31148] = {id=31148,name="Novice Elreth",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=85,mapID=18,description="Actually, before I go - you should speak with Novice Elreth. She had some work for you, and you would do well to help others and improve your skills. The next time you see me, I will be in Undercity.",questType="standard"},
[31152] = {id=31152,name="Peering Into the Past",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Just a moment, now. Allow me to gather my things. Wouldn't want me to lose these notes now, would we? Especially after you risked life and limb for them! There, all set. Let us be off, shall we? I must say, I feel much safer traveling with you after seeing how you handled that saurok!",starts={{npcID=63217,x=0.308,y=0.34,mapID=371}},ends={{npcID=63307,x=0.288,y=0.326,mapID=371}},coords={x=0.308,y=0.34,source="quest_giver",mapID=371},questType="standard"},
[31153] = {id=31153,name="Tracking Event - Saved Diaani",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31154] = {id=31154,name="Tracking Event - Saved Zuulo",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31162] = {id=31162,name="The Arts of a Monk",level=0,requiredLevel=0,faction="horde",expansion=4,zoneID=6453,mapID=463,description="As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do. Wanna see? Go, train up some, and learn someting new. 'Den come back and ya can show me.",starts={{npcID=63310,x=0.524,y=0.518,mapID=463}},ends={{npcID=63310,x=0.524,y=0.518,mapID=463}},coords={x=0.524,y=0.518,source="quest_giver",mapID=463},questType="standard"},
[31172] = {id=31172,name="Monk Training",level=5,requiredLevel=5,faction="none",expansion=4,questType="standard"},
[31206] = {id=31206,name="The Crucible of Carnage: The Bloodeye Bruiser!",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=4922,mapID=241,description="I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal. You're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match. If you're ready and got a group of friends with you, we can start! What do you say?",questType="group"},
[31212] = {id=31212,name="FLAG - Chose Tenwu",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31213] = {id=31213,name="FLAG - Chose Taoshi",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31214] = {id=31214,name="FLAG - Chose Nurong",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31218] = {id=31218,name="FLAG - Unlocked Tenwu",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31219] = {id=31219,name="FLAG - Unlocked Nurong",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5842,mapID=388,questType="standard"},
[31221] = {id=31221,name="The Challenger's Ring: Tenwu of the Red Smoke",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,mapID=388,description="So... you've been challenged by the infamous Tenwu of the Red Smoke. That's what he calls himself, at least. He's a good fighter, and a good rogue, but it's a wonder he manages to sneak up on anyone with how loudly he brags about himself. Anyways, I think you should answer the challenge. Maybe it'll give him a touch of humility. Maybe not. Either way, if you win, he'll probably be willing to go with you on your missions. And I get some entertainment.",starts={{npcID=63614,x=0.49,y=0.712,mapID=388}},ends={{npcID=63614,x=0.49,y=0.712,mapID=388}},coords={x=0.49,y=0.712,source="quest_giver",mapID=388},questType="standard"},
[31239] = {id=31239,name="What's in a Name Name?",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="So, you wanna be a hozen. Huh, wikket? Hozen defend their lands from enemies, like jinyu. Kah Kah fought many jinyu fights, and won them all. Hozen only give name name to good grookers. Go grook jinyu and maybe they call you . Jinyu creepin' down by the river. Ook 'em in the dooker!",starts={{npcID=56336,x=0.28,y=0.47,mapID=371}},ends={{npcID=56336,x=0.28,y=0.47,mapID=371}},coords={x=0.28,y=0.47,source="quest_giver",mapID=371},questType="standard"},
[31255] = {id=31255,name="The Road to Kun-Lai",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=6006,mapID=379,description="Ah! Greetings friend of Lorewalker Cho. I have a message for you. The Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous. Look for guides along the road to help you find your way.",starts={{npcID=63778,x=0.458,y=0.438,mapID=371},{npcID=63778,x=0.7,y=0.236,mapID=376},{npcID=63778,x=0.404,y=0.34,mapID=418}},ends={{npcID=59073,x=0.722,y=0.918,mapID=379}},coords={x=0.458,y=0.438,source="quest_giver",mapID=379},questType="standard"},
[31274] = {id=31274,name="LFGDungeons - Mists - Raid Finder - 1st",level=35,requiredLevel=35,faction="none",expansion=4,questType="standard"},
[31278] = {id=31278,name="Figuring out how to make quests",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5042,mapID=207,description="Whee! You get to make a breadcrumb quest! Now figure out what to do next.",questType="standard"},
[31280] = {id=31280,name="Ways of Cooking",level=5,requiredLevel=5,faction="both",expansion=4,zoneID=5042,mapID=207,description="There are many ways of cooking, and each creates dishes with unique properties. The Pandaren Ways of Cooking are the Ways of the Grill, the Wok, the Pot, the Steamer, the Oven and the Brew. You seem to already have the basics of each way, from your experience in faraway lands. If you wish to progress further, speak with my siblings and learn the first advanced recipe each of them teaches. Find out which Way suits you the best.",questType="standard"},
[31281] = {id=31281,name="So You Want to Be a Chef...",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,mapID=376,description="You wish to be a chef? If you are dedicated, I can unlock your hidden potential, no matter how inexperienced you are. If you wish to learn, show me you can at least follow basic instructions. Learn how to slice peaches and show me what you've learned. I have fresh pandaren peaches which I will sell to you at a token price.",starts={{npcID=64231,x=0.536,y=0.512,mapID=376}},ends={{npcID=64231,x=0.536,y=0.512,mapID=376}},coords={x=0.536,y=0.512,source="quest_giver",mapID=376},questType="standard"},
[31284] = {id=31284,name="FLAG - Ancient Pandaren Fishing Pole",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31292] = {id=31292,name="FLAG - Ancient Pandaren Woodcutter",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31304] = {id=31304,name="FLAG - Kafa Press",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31306] = {id=31306,name="Seeker's Folly",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,mapID=379,description="I'm sure your pandaren friend has some ideas about what the mogu are after. He headed up the mountain a few days ago without a guide, and asked that only you be sent up after him. He was very specific: \"The must endure the trek alone, with only thoughts. will honor each shrine before meeting me at the top.\" The path is just northwest of the camp, marked by flags. Please be careful! Seeker's Folly is a dangerous trek even on a lucky day.",starts={{npcID=60180,x=0.48,y=0.49,mapID=379}},ends={{npcID=60795,x=0.438,y=0.51,mapID=379}},coords={x=0.48,y=0.49,source="quest_giver",mapID=379},questType="standard"},
[31307] = {id=31307,name="FLAG - Jade Infused Blade",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[31308] = {id=31308,name="Learning the Ropes",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=12,mapID=37,description="Now that you are a pet trainer, it's time to test your skills! Head out into the forest and pick a fight with a battle pet. Make sure to use your Track Pets skill so you can see pets you can fight on the minimap. Come back to me after you have won and I will continue your training. Good luck!",starts={{npcID=63014,x=0.402,y=0.66,mapID=37}},ends={{npcID=63014,x=0.402,y=0.66,mapID=37}},coords={x=0.402,y=0.66,source="quest_giver",mapID=37},questType="standard"},
[31309] = {id=31309,name="On The Mend",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=12,mapID=37,description="Now that you have won a battle, we need to heal up your pets so they can fight another day! Visit Erma, our local stable master, to heal and revive your pets.",starts={{npcID=63014,x=0.402,y=0.66,mapID=37}},ends={{npcID=63014,x=0.402,y=0.66,mapID=37}},coords={x=0.402,y=0.66,source="quest_giver",mapID=37},questType="standard"},
[31312] = {id=31312,name="The Old Map",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="The old, faded leather is falling apart, but still legible. Scrawled on it is some kind of map, and the following lines: Deep in the valley where four winds blow, The maiden laughs behind her golden fan. At the feet of her ancestors' stair, She whispers secrets into the echoing dark.",ends={{npcID=58705,x=0.528,y=0.518,mapID=376}},questType="standard"},
[31325] = {id=31325,name="A Very Nice Necklace",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="The beautiful necklace is only partly smudged by dirty hozen hands. There's only one person in the Valley who would own such a beautiful piece of jewelry.",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31326] = {id=31326,name="Tina's Tasteful Tiara",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="It's a dazzling diamond tiara. Who in the valley would be wealthy enough to own such a piece of jewelry? Whoever it is, they might be willing to give a nice reward.",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31328] = {id=31328,name="An Exquisite Earring",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="You unhook the earring off the furry creature's ear. It looks like he was having some fun wearing the dangly hoop. TOO much fun. Perhaps the owner of this dainty bauble would like to see it returned. You don't have to tell her where you found it... or who was wearing it.",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31329] = {id=31329,name="A Beautiful Brooch",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="It is a very old, antique brooch with very detailed molding and filigree worked into the edges. It looks very valuable. There's only one person who keeps losing jewelry to furry hooligans, and she would probably want to see this heirloom returned.",ends={{npcID=58761,x=0.45,y=0.338,mapID=376}},questType="standard"},
[31331] = {id=31331,name="Figuring out how to make quests",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5042,mapID=207,description="Whee! You get to make a breadcrumb quest! Now figure out what to do next.",questType="standard"},
[31354] = {id=31354,name="Mazu's Bounty",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="That was some amazing work you and the captain did out there, $p! It's an honor to have you on the crew. Oh! And Ju Lien survived! He swam ashore just after you started letting the harpoons fly. He was raving about some kind of gigantic egg or something that washed in with Jiao. Go check up on him, will you? He's probably hauled it out of the water by now.",starts={{npcID=63349,x=0.548,y=0.722,mapID=422}},ends={{npcID=64259,x=0.536,y=0.76,mapID=422}},coords={x=0.548,y=0.722,source="quest_giver",mapID=422},questType="standard"},
[31355] = {id=31355,name="Restoring Jade's Purity",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5956,description=", will you aid us? The temple's purity has been jeopardized. Even now the three masters struggle against their doubts. Please, I beg you, head in and help Wise Mari, Liu Flameheart, and Lorewalker Stonestep in their fight against the sha.",questType="dungeon"},
[31360] = {id=31360,name="A New Lesson for the Master",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6182,description="A new king of the mogu has arisen: Xin the Weaponmaster . He single-handedly subjugated the mogu clans, and now they and their new leaders vie for his favor. I've never seen or read of any who are his equal in battle. Do not underestimate Xin, . Our fate rests in your hands.",questType="dungeon"},
[31362] = {id=31362,name="Last Piece of the Puzzle",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="I must say, , despite their skirmishes with the hozen, I've never seen the jinyu so militant. This troubles me. We must discuss it another time, however. I have come to ask for your assistance. The fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor would have us remember. My meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.",starts={{npcID=59620,x=0.588,y=0.81,mapID=371}},ends={{npcID=59411,x=0.446,y=0.67,mapID=371}},coords={x=0.588,y=0.81,source="quest_giver",mapID=371},questType="standard"},
[31364] = {id=31364,name="That's a Big Bug!",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5976,description="The mantid have something they call Raigonn . It's a giant bug they're using to bust down the wall's gates! Let's keep that thing from getting into the vale!",questType="dungeon"},
[31365] = {id=31365,name="Somewhere Inside",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=6214,description="I sent a dozen of my best men ahead to infiltrate the mantid siege. None have returned. Since you are taking the fight directly to the mantid, you will be in a position to free any who had the misfortune to be captured. You will do this?",starts={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},ends={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},coords={x=0.58,y=0.23,source="quest_giver",zoneID=6214},questType="dungeon"},
[31366] = {id=31366,name="Take Down the Wing Leader",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=6214,description="The mantid have lain siege to Niuzao Temple. Even now, Wing Leader Ner'onok and his forces work to cross the final chasm. You must stop him before they reconstruct that bridge.",starts={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},ends={{npcID=64517,x=0.58,y=0.23,zoneID=6214},{npcID=64517,zoneID=6214}},coords={x=0.58,y=0.23,source="quest_giver",zoneID=6214},questType="dungeon"},
[31367] = {id=31367,name="The Lorewalkers",level=30,requiredLevel=30,faction="alliance",expansion=4,zoneID=5840,mapID=1530,description="So you are interested in learning more of the lore of this land? Very well! You should speak to Lorewalker Cho at the Seat of Knowledge. He can be found in the room above the entrance to the Mogu'shan Palace. Speak with Mishi for a ride.",starts={{npcID=64508,x=0.854,y=0.602,mapID=1530}},ends={{npcID=61962,x=0.832,y=0.296,mapID=1530}},coords={x=0.854,y=0.602,source="quest_giver",mapID=1530},questType="standard"},
[31370] = {id=31370,name="The Anglers",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="If you want to explore all the secrets of the deep ocean, and catch some big fish, speak to Haito at the Anglers Wharf in Krasarang Wilds . I'm sure he'd love to show you a thing or two about reeling!",starts={{npcID=64010,x=0.608,y=0.234,mapID=1530}},ends={{npcID=59584,x=0.678,y=0.452,mapID=418}},coords={x=0.608,y=0.234,source="quest_giver",mapID=418},questType="standard"},
[31376] = {id=31376,name="Attack At The Temple of the Jade Serpent",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid. They hold the sha in check, but just barely. You may be able to turn the tide, .",starts={{npcID=64032,x=0.846,y=0.636,mapID=1530}},ends={{npcID=57324,x=0.538,y=0.618,mapID=371}},coords={x=0.846,y=0.636,source="quest_giver",mapID=371},questType="standard"},
[31377] = {id=31377,name="Attack At The Temple of the Jade Serpent",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="Darkness enshrouds the Temple of the Jade Serpent, and Yu'Lon's priests beseech us for aid. They hold the sha in check, but just barely. You may be able to turn the tide, .",starts={{npcID=64001,x=0.626,y=0.232,mapID=1530}},ends={{npcID=57324,x=0.538,y=0.618,mapID=371}},coords={x=0.626,y=0.232,source="quest_giver",mapID=371},questType="standard"},
[31385] = {id=31385,name="The Golden Lotus",level=30,requiredLevel=30,faction="horde",expansion=4,zoneID=5840,mapID=1530,description="The Golden Lotus have guarded the Vale for centuries, keeping it safe and hidden from harm. Recent events have unleashed terrible horrors upon our sacred vale, but allies of the Golden Lotus still stand against them, attempting to bring peace. If you wish to help, you had best join them at the Setting Sun Garrison.",starts={{npcID=64007,x=0.63,y=0.222,mapID=1530}},ends={{npcID=58408,x=0.566,y=0.436,mapID=1530},{npcID=58919,x=0.214,y=0.716,mapID=1530}},coords={x=0.63,y=0.222,source="quest_giver",mapID=1530},questType="standard"},
