[31440] = {id=31440,name="The Four Tomes",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6066,description="There are four tomes of great necromantic evil studied in Scholomance : \" In the Shadow of the Light \", \" Kel'Thuzad's Deep Knowledge \", \" Forbidden Rites and other Rituals Necromantic \" and \" The Dark Grimoire \". As we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.",questType="dungeon"},
[31442] = {id=31442,name="The Four Tomes",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6066,description="There are four tomes of great necromantic evil studied in Scholomance : \" In the Shadow of the Light \", \" Kel'Thuzad's Deep Knowledge \", \" Forbidden Rites and other Rituals Necromantic \" and \" The Dark Grimoire \". As we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.",questType="dungeon"},
[31443] = {id=31443,name="Flying Tiger Gourami",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6006,mapID=379,description="You've caught a unique fish... with wings. Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.",ends={{npcID=63721,x=0.684,y=0.434,mapID=418}},questType="standard"},
[31444] = {id=31444,name="Spinefish Alpha",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6757,mapID=554,description="You have fished up something special. It looks pretty aggressive. Maybe Nat Pagle at the Anglers Wharf might know more about it?",ends={{npcID=63721,x=0.684,y=0.434,mapID=418}},questType="standard"},
[31445] = {id=31445,name="zzOld",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[31446] = {id=31446,name="Mimic Octopus",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6661,description="You aren't sure how, but you've caught an extraordinary cephalopod. Nat Pagle at Anglers Wharf would be very interested to see it.",ends={{npcID=63721,x=0.684,y=0.434,mapID=418}},questType="standard"},
[31465] = {id=31465,name="Extracting Answers",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Kypari Ik is just one of many locations that houses some of Empress Shek'zeer's offspring. In their juvenile state the young are reckless and difficult to control. They are also deadly. Swarmborn are hatched with a highly toxic venom that diminishes in potency with age. The venom can incapacitate even the strongest and most skilled fighter if it hits flesh. I would like you to bring me some of this venom.",starts={{npcID=63785,x=0.548,y=0.36,mapID=422},{npcID=64705,x=0.562,y=0.576,mapID=422},{npcID=65454,x=0.562,y=0.582,mapID=422}},ends={{npcID=63785,x=0.548,y=0.36,mapID=422}},coords={x=0.548,y=0.36,source="quest_giver",mapID=422},questType="standard"},
[31478] = {id=31478,name="Way of the Oven",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,mapID=376,description="If you are looking for a hearty meal that will sustain you and increase your stamina, you should seek out the Way of the Oven . Bring some wildfowl breasts to the Master of the Oven and she will teach you. There are plenty of cranes in the Valley of the Four Winds and in the Jade Forest, but you can obtain wildfowl breasts from other birds as well.",starts={{npcID=64231,x=0.536,y=0.512,mapID=376}},ends={{npcID=58716,x=0.532,y=0.516,mapID=376}},coords={x=0.536,y=0.512,source="quest_giver",mapID=376},questType="standard"},
[31516] = {id=31516,name="Unto Dust Thou Shalt Return",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6109,mapID=18,questType="dungeon"},
[31518] = {id=31518,name="The Vale of Eternal Blossoms",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,questType="standard"},
[31525] = {id=31525,name="A Worthy Challenge: Wing Leader Ner'onok",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,mapID=1530,description=", I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple . Activate the Challenger's Orb and ground Wing Leader Ner'onok. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,mapID=1530}},ends={{npcID=63994,x=0.612,y=0.208,mapID=1530}},coords={x=0.612,y=0.208,source="quest_giver",mapID=1530},questType="dungeon"},
[31526] = {id=31526,name="A Worthy Challenge: Durand",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,mapID=1530,description=", I need you to assemble a stout group and lead them into Scarlet Monastery . Activate the Challenger's Orb therein, and smite Durand with righteous fury. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,mapID=1530}},ends={{npcID=63994,x=0.612,y=0.208,mapID=1530}},coords={x=0.612,y=0.208,source="quest_giver",mapID=1530},questType="dungeon"},
[31529] = {id=31529,name="Mission: Culling The Vermin",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I was sent to this valley to protect The Heartland from any potential threats. I've identified a high priority target. The Springtail vermin burrow into the mountain cliffs, high above the farmlands. Left unchecked, their numbers will multiply, and they will make their way down to the fields below. They must be eliminated.",starts={{npcID=58708,x=0.53,y=0.52,mapID=376}},ends={{npcID=58708,x=0.53,y=0.52,mapID=376}},coords={x=0.53,y=0.52,source="quest_giver",mapID=376},questType="standard"},
[31530] = {id=31530,name="Mission: The Hozen Dozen",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=5840,mapID=1530,description="I've been watching the hozen since I arrived, and I don't like the pattern of activity that I'm seeing in their camp. Multiple hozen travel down the mountain under the cover of night, pillaging supplies from the farmlands below. We must stop their rampant theft. I have been thinning their numbers when I can, but one soldier alone is not enough. I need your help. Kill as many of the hozen as you can.",questType="standard"},
[31535] = {id=31535,name="Replenishing the Pantry",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,mapID=376,description="People come from all over Pandaria to learn cooking from the Ironpaw family. We take great pride not only in being the best chefs, but also in passing what we know onto others. That's why we try to charge as little as possible for cooking lessons. This means, however, that we often find ourselves in shortage of cooking ingredients for the lessons. Would you donate some to the school, to help out students who cannot afford it?",starts={{npcID=64395,x=0.534,y=0.512,mapID=376}},ends={{npcID=64395,x=0.534,y=0.512,mapID=376}},coords={x=0.534,y=0.512,source="quest_giver",mapID=376},questType="standard"},
[31542] = {id=31542,name="Incarnadine Ink",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="The practice of caligraphy is an old custom in Pandaria. I am working on a piece about an ancient war, so I seek an ink that is suitable to the subject matter. I have searched high and low for the right hue, but it eludes me. Can you think of a way to achieve the color I am seeking?",starts={{npcID=56064,x=0.548,y=0.452,mapID=371}},ends={{npcID=56064,x=0.548,y=0.452,mapID=371}},coords={x=0.548,y=0.452,source="quest_giver",mapID=371},questType="standard"},
[31543] = {id=31543,name="Portrait of a Lady",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Many great pieces of art are results of great love. A merchant in Halfhill wishes to have a portrait made for his beloved, as a birthday present. Will you accept this commission?",starts={{npcID=56064,x=0.548,y=0.452,mapID=371}},ends={{npcID=56064,x=0.548,y=0.452,mapID=371}},coords={x=0.548,y=0.452,source="quest_giver",mapID=371},questType="standard"},
[31545] = {id=31545,name="The Finer Things",level=10,requiredLevel=10,faction="none",expansion=4,description="The Pandaria Treasure Society is interested in purchasing finely crafted goods from skilled jewelcrafters such as yourself. The items will be catalogued, and the most exceptional cuts stored in a secret vault, while the rest are sold to refresh our funds. Our goal is to eventually create a unique collection for a special event.",questType="standard"},
[31554] = {id=31554,name="On The Mend",level=5,requiredLevel=5,faction="both",expansion=4,description="Now that you have one a battle, we need to heal up your pets so they can fight another day! Visit Seriadne, our local stable master to heal and revive your pets.",questType="standard"},
