[31581] = {id=31581,name="Got one!",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=3430,mapID=94,description="Great work so far, ! You are going to be a pro at this pet stuff before you know it. Now it's time to catch a pet of your own! Head back out and find a battle pet to fight, engage it in battle, and throw your trap once it's low on health. Bring your catch back for me to see once you are finished. Remember, you need at least one pet at level 3 to use your trap!",starts={{npcID=63080,x=0.472,y=0.472,mapID=94}},ends={{npcID=63080,x=0.472,y=0.472,mapID=94}},coords={x=0.472,y=0.472,source="quest_giver",mapID=94},questType="standard"},
[31585] = {id=31585,name="Learning the Ropes",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,mapID=85,description="Now that you are a pet trainer, it's time to test your skills! Head out into the wild and pick a fight with a battle pet. Come back to me after you have won and I will continue your training. Good luck!",starts={{npcID=63086,x=0.368,y=0.774,mapID=85}},ends={{npcID=63086,x=0.368,y=0.774,mapID=85}},coords={x=0.368,y=0.774,source="quest_giver",mapID=85},questType="standard"},
[31586] = {id=31586,name="On The Mend",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,mapID=85,description="Now that you have won a battle, we need to heal up your pets so they can fight another day! Visit Bezzil, our local stable master, to heal and revive your pets.",starts={{npcID=63086,x=0.368,y=0.774,mapID=85}},ends={{npcID=63086,x=0.368,y=0.774,mapID=85}},coords={x=0.368,y=0.774,source="quest_giver",mapID=85},questType="standard"},
