[31664] = {id=31664,name="An Angler's Quest",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=6757,mapID=554,description="This journal provides a hazy recollection of Nat Pagle's grand adventures. Simply reading it will undoubtedly provide a useful insight into fishing.",questType="standard"},
