[31670] = {id=31670,name="That Dangling Carrot",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Grandpa always said, \"Carrots ain't nothin but a welcomin' mat for virmen.\" I don't think I ever saw him grow a single carrot. For once, I disagree with Grandpa. I like to live on the edge. Plus, I like to eat carrots. I like to eat carrots on the edge. Could you get some seeds and grow one for me?",starts={{npcID=58646,x=0.522,y=0.488,mapID=376}},ends={{npcID=58646,x=0.522,y=0.488,mapID=376}},coords={x=0.522,y=0.488,source="quest_giver",mapID=376},questType="standard"},
[31676] = {id=31676,name="Ancient Vengeance",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="I can hear them howling in rage... The spirits of the Gurthani mogu I slew so long ago. They wander this ruined terrace, seeking vengeance. If they find me in this state, I will not have the strength to fend them off. Draw their attention and put them down. Finish what I started, and I will tell you who I am.",starts={{npcID=62202,x=0.702,y=0.256,mapID=422}},ends={{npcID=62202,x=0.702,y=0.256,mapID=422}},coords={x=0.702,y=0.256,source="quest_giver",mapID=422},questType="standard"},
[31677] = {id=31677,name="The Warlord's Ashes",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Kil'ruk the Wind-Reaver defeated Warlord Gurthan centuries ago, but the mogu beastmaster's spirit continues to haunt the ruins of his old stronghold. Showing proof of your victory over this spirit may gain you favor in the eyes of the Klaxxi.>",ends={{npcID=62538,x=0.55,y=0.358,mapID=422}},questType="standard"},
[31679] = {id=31679,name="Extending Our Coverage",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The Klaxxi 'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened. There is a tower in Amberglow Hollow that has been silent for many years. It must sing; The Klaxxi demand it! This time I will go with you. You will help me repair it. Take the resonating crystal and meet me in Amberglow.",starts={{npcID=65541,x=0.548,y=0.34,mapID=422}},ends={{npcID=65542,x=0.48,y=0.496,mapID=422}},coords={x=0.548,y=0.34,source="quest_giver",mapID=422},questType="standard"},
[31680] = {id=31680,name="Crime and Punishment",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken. The Klaxxi 'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters .",starts={{npcID=65975,x=0.48,y=0.496,mapID=422}},ends={{npcID=65975,x=0.48,y=0.496,mapID=422}},coords={x=0.48,y=0.496,source="quest_giver",mapID=422},questType="standard"},
[31681] = {id=31681,name="Better With Age",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="It is a crime to harvest the young trees, but a much bigger crime to waste the amber. Young amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises! Gather the young amber. We will store it until it is aged and can be consumed.",starts={{npcID=65975,x=0.48,y=0.496,mapID=422}},ends={{npcID=65975,x=0.48,y=0.496,mapID=422}},coords={x=0.48,y=0.496,source="quest_giver",mapID=422},questType="standard"},
[31685] = {id=31685,name="Valley of the Four Winds",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Yarr, the Jade Forest be goin through some violent reconstruction, but the Valley of the Four Winds is ripe for explorin. Talk with me when ye be ready to go and I can give ye a ride ta where ya need to go. Talk to me cohort on the other side 'ta get some equipment to aid ya on yer journey.",starts={{npcID=65563,x=0.628,y=0.718,mapID=84},{npcID=65563,x=0.504,y=0.76,mapID=85}},ends={{npcID=65564,x=0.86,y=0.22,mapID=376}},coords={x=0.628,y=0.718,source="quest_giver",mapID=376},questType="standard"},
[31693] = {id=31693,name="Julia Stevens",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=12,mapID=37,description="Think you can take me again?",starts={{npcID=64330,x=0.416,y=0.836,mapID=37}},ends={{npcID=64330,x=0.416,y=0.836,mapID=37}},coords={x=0.416,y=0.836,source="quest_giver",mapID=37},questType="standard"},
[31694] = {id=31694,name="Hisingen Blues",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=4471,questType="standard"},
[31700] = {id=31700,name="The Shoe Is On The Other Foot",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="I loathe sprites! One time, one of those nasty buggers followed me all day, putting dirt in my tea and bugs in my hair. I mean, who does that!? Well, I think it's time for a little payback. Do you know what the sprites up at Windward Isle love more than anything in the world? Yeah, you guessed it. Shoes! And we're going to steal them. Won't that make them mad! Hah! Well, I'm scared to go near sprites, so you'll have to do it, .",starts={{npcID=58509,x=0.582,y=0.45,mapID=371}},ends={{npcID=58564,x=0.576,y=0.448,mapID=371}},coords={x=0.582,y=0.45,source="quest_giver",mapID=371},questType="standard"},
[31723] = {id=31723,name="Valley of the Four Winds",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=5805,mapID=376,questType="standard"},
[31780] = {id=31780,name="Old MacDonald",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=40,mapID=52,description="I won't be such a pushover this time around!",starts={{npcID=65648,x=0.608,y=0.186,mapID=52}},ends={{npcID=65648,x=0.608,y=0.186,mapID=52}},coords={x=0.608,y=0.186,source="quest_giver",mapID=52},questType="standard"},
[31781] = {id=31781,name="Lindsay",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=44,mapID=49,description="Think you can take me again? I'm always up for challenge!",starts={{npcID=65651,x=0.332,y=0.526,mapID=49}},ends={{npcID=65651,x=0.332,y=0.526,mapID=49}},coords={x=0.332,y=0.526,source="quest_giver",mapID=49},questType="standard"},
[31786] = {id=31786,name="Pristine Manacles of Rebellion",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5840,mapID=1530,description="This artifact has been restored to a remarkably excellent condition. Perhaps you will put it on display at the Seat of Knowledge , so that lorewalkers and archaeologists can study it.",ends={{npcID=214205,x=0.827,y=0.317,mapID=1530}},questType="standard"},
