[31926] = {id=31926,name="Grand Master Antari",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=3520,mapID=104,description="You capitalized on my mistake last time and emerged victorious. This time, you will not be so fortunate, .",starts={{npcID=66557,x=0.304,y=0.418,mapID=104}},ends={{npcID=66557,x=0.304,y=0.418,mapID=104}},coords={x=0.304,y=0.418,source="quest_giver",mapID=104},questType="standard"},
[31932] = {id=31932,name="Nearly Headless Jacob",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=2817,mapID=127,description="Time and time again you defy my wisdom. What is it that brings you back to these woods? Ah, you wish to do battle once more. Very well then.",starts={{npcID=66636,x=0.62,y=0.496,mapID=71},{npcID=66636,x=0.502,y=0.59,mapID=127}},ends={{npcID=66636,x=0.62,y=0.496,mapID=71},{npcID=66636,x=0.502,y=0.59,mapID=127}},coords={x=0.62,y=0.496,source="quest_giver",mapID=127},questType="standard"},
[31933] = {id=31933,name="Okrut Dragonwaste",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=65,mapID=115,description="You dare interrupt our work? Then you must battle me again! Take out your pets, and I'll give you a taste of Hellscream's wrath!",starts={{npcID=66638,x=0.59,y=0.77,mapID=115}},ends={{npcID=66638,x=0.59,y=0.77,mapID=115}},coords={x=0.59,y=0.77,source="quest_giver",mapID=115},questType="standard"},
[31934] = {id=31934,name="Gutretch",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=440,mapID=71,description="Me like fighting you. You not so easy like the others. We fight again?",starts={{npcID=66639,x=0.132,y=0.668,mapID=121},{npcID=66639,x=0.62,y=0.496,mapID=71}},ends={{npcID=66639,x=0.132,y=0.668,mapID=121},{npcID=66639,x=0.62,y=0.496,mapID=71}},coords={x=0.132,y=0.668,source="quest_giver",mapID=71},questType="standard"},
[31935] = {id=31935,name="Grand Master Payne",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=210,mapID=118,description="The rebel comes once again to test might again that of a Grand Master. Your bravery will be your undoing this time!",starts={{npcID=66675,x=0.774,y=0.196,mapID=118}},ends={{npcID=66675,x=0.774,y=0.196,mapID=118}},coords={x=0.774,y=0.196,source="quest_giver",mapID=118},questType="standard"},
[31945] = {id=31945,name="Learn and Grow VI: Gina's Vote",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="My business is doomed! You see all of the Ironpaws at their cooking stations? Their tasty dishes draw many of the customers to this market, but they're all out of scallions ! It may not look like much, but the scallion is an essential cooking ingredient. Without it, foods are less savory, less flavorful, and less aromatic. This is terrible. I'm not getting another scallion shipment for a week! Wait a second. You're a farmer, aren't you? You think you could help me?",starts={{npcID=58706,x=0.532,y=0.516,mapID=376}},ends={{npcID=58706,x=0.532,y=0.516,mapID=376}},coords={x=0.532,y=0.516,source="quest_giver",mapID=376},questType="standard"},
[31952] = {id=31952,name="Battle Pet Tamers: Pandaria",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=5842,mapID=388,description="You must now face the toughest tamers in all of Azeroth, . They make their home in Pandaria, training ground of the grand masters. There are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes. If you think yourself ready, seek out these champions of the trade and prove yourself!",starts={{npcID=63626,x=0.524,y=0.592,mapID=85}},coords={x=0.524,y=0.592,source="quest_giver",mapID=388},questType="standard"},
[31953] = {id=31953,name="Grand Master Hyuna",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5785,mapID=371,description="You seek to do battle once more? Very well, it will strengthen me to better protect the sacred sites of my people.",starts={{npcID=66730,x=0.48,y=0.54,mapID=371}},ends={{npcID=66730,x=0.48,y=0.54,mapID=371}},coords={x=0.48,y=0.54,source="quest_giver",mapID=371},questType="standard"},
[31954] = {id=31954,name="Grand Master Mo'ruk",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,description="This time I'm gonna do the beating! You watch!",starts={{npcID=66733,x=0.622,y=0.458,mapID=418}},ends={{npcID=66733,x=0.622,y=0.458,mapID=418}},coords={x=0.622,y=0.458,source="quest_giver",mapID=418},questType="standard"},
[31955] = {id=31955,name="Grand Master Nishi",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5805,mapID=376,description="My pets continue to grow in strength thanks to the fertile land we train on. You don't stand a chance!",starts={{npcID=66734,x=0.46,y=0.436,mapID=376}},ends={{npcID=66734,x=0.46,y=0.436,mapID=376}},coords={x=0.46,y=0.436,source="quest_giver",mapID=376},questType="standard"},
[31956] = {id=31956,name="Grand Master Yon",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5841,mapID=379,description="If you think I am going to let you walk away with another victory in hand, you are sorely mistaken. This time, I will stand over you as the superior trainer!",starts={{npcID=66738,x=0.358,y=0.736,mapID=379}},ends={{npcID=66738,x=0.358,y=0.736,mapID=379}},coords={x=0.358,y=0.736,source="quest_giver",mapID=379},questType="standard"},
[31957] = {id=31957,name="Grand Master Shu",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6138,mapID=422,description="You venture into the heart of the wastes to face me again, only to suffer defeat at the hands of a true grand master. Noble, but foolish.",starts={{npcID=66739,x=0.55,y=0.374,mapID=422}},ends={{npcID=66739,x=0.55,y=0.374,mapID=422}},coords={x=0.55,y=0.374,source="quest_giver",mapID=422},questType="standard"},
[31958] = {id=31958,name="Grand Master Aki",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=9105,mapID=1530,description="You wish to test yourself against me once more? Very well, let us fight.",starts={{npcID=66741,x=0.312,y=0.742,mapID=1530},{npcID=66741,x=0.84,y=0.286,mapID=1530}},ends={{npcID=66741,x=0.312,y=0.742,mapID=1530},{npcID=66741,x=0.84,y=0.286,mapID=1530}},coords={x=0.312,y=0.742,source="quest_giver",mapID=1530},questType="standard"},
