[31972] = {id=31972,name="Brok",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=616,mapID=198,description="I do not yet understand the plight of these creatures well enough to help them sufficiently. Perhaps another battle would strengthen our bond?",starts={{npcID=66819,x=0.62,y=0.496,mapID=71},{npcID=66819,x=0.614,y=0.328,mapID=198}},ends={{npcID=66819,x=0.62,y=0.496,mapID=71},{npcID=66819,x=0.614,y=0.328,mapID=198}},coords={x=0.62,y=0.496,source="quest_giver",mapID=198},questType="standard"},
[31973] = {id=31973,name="Bordin Steadyfist",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5042,mapID=207,description="The natives have taught me the strength of the earth. I know it's unending endurance. Let us battle once more, and you'll see that I'm tougher than ever!",starts={{npcID=66815,x=0.62,y=0.496,mapID=71},{npcID=66815,x=0.498,y=0.57,mapID=207}},ends={{npcID=66815,x=0.62,y=0.496,mapID=71},{npcID=66815,x=0.498,y=0.57,mapID=207}},coords={x=0.62,y=0.496,source="quest_giver",mapID=207},questType="standard"},
[31974] = {id=31974,name="Goz Banefury",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=4922,mapID=241,description="The power of twilight flows through me. I am a god! You have no hope of defeating me!",starts={{npcID=66822,x=0.62,y=0.496,mapID=71},{npcID=66822,x=0.566,y=0.568,mapID=241}},ends={{npcID=66822,x=0.62,y=0.496,mapID=71},{npcID=66822,x=0.566,y=0.568,mapID=241}},coords={x=0.62,y=0.496,source="quest_giver",mapID=241},questType="standard"},
