[31991] = {id=31991,name="Grand Master Zusshi",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,description="I knew you would return to face me once more. Let us see who is truly wiser in the ways of battle.",starts={{npcID=66918,x=0.362,y=0.522,mapID=388}},ends={{npcID=66918,x=0.362,y=0.522,mapID=388}},coords={x=0.362,y=0.522,source="quest_giver",mapID=388},questType="standard"},
[32000] = {id=32000,name="A Worthy Challenge: Yan-zhu the Uncasked",level=35,requiredLevel=35,faction="alliance",expansion=4,zoneID=5840,mapID=1530,description=", I need you to assemble a hearty group and lead them into Stormstout Brewery . Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=64028,x=0.862,y=0.614,mapID=1530}},ends={{npcID=64028,x=0.862,y=0.614,mapID=1530}},coords={x=0.862,y=0.614,source="quest_giver",mapID=1530},questType="dungeon"},
