[32030] = {id=32030,name="Once in a Hundred Lifetimes",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="The time has come, wakener. The council's power will combine to bring an end to the corrupted empress. This ritual has not been witnessed in one hundred of your kind's lifetimes - and never by an outsider. In exchange for your deeds on our behalf, I invite you to behold this great moment in our history.",starts={{npcID=62667,x=0.506,y=0.118,mapID=422},{npcID=64259,x=0.536,y=0.76,mapID=422}},ends={{npcID=65395,x=0.546,y=0.346,mapID=422}},coords={x=0.506,y=0.118,source="quest_giver",mapID=422},questType="standard"},
