[32098] = {id=32098,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=4,questType="standard"},
[32099] = {id=32099,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=4,questType="standard"},
[32105] = {id=32105,name="Pristine Monument Ledger",level=10,requiredLevel=10,faction="none",expansion=4,description="This artifact has been restored to a remarkably excellent condition. Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.",questType="standard"},
[32106] = {id=32106,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[32107] = {id=32107,name="Flying Tiger Gourami",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=6006,mapID=379,description="You've caught a unique fish... with wings. Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.",questType="standard"},
[32112] = {id=32112,name="FLAG - Been to Fight Club",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6138,mapID=422,questType="standard"},
[32113] = {id=32113,name="FLAG - Been to Fight Club Today",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6138,mapID=422,questType="standard"},
[32114] = {id=32114,name="So, You Wanted to Test Daily Quests?",level=1,requiredLevel=1,faction="both",expansion=4,description="You wanna test dailies? Well alright then.",questType="standard"},
[32127] = {id=32127,name="All Dead, All Dead",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Our Warchief has dispatched me to these shores to deal with this pitiful Alliance threat. These humans and their allies have proven to be very dependent on their leaders. No initiative of their own. As you walk the battlefield today look to the Alliance ships off our southern shores. Find their captains. Slay them. For the Horde!",starts={{npcID=67767,x=0.102,y=0.538,mapID=418}},ends={{npcID=67767,x=0.102,y=0.538,mapID=418}},coords={x=0.102,y=0.538,source="quest_giver",mapID=418},questType="standard"},
[32129] = {id=32129,name="Defense Daily 06",level=15,requiredLevel=15,faction="horde",expansion=4,questType="standard"},
[32138] = {id=32138,name="Work Order: Lumber",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Everyday it's the same thing! \"We're out of this!\", \"We need more of that!\", \"Why don't you ever do anything?!\" I work! I do things! They can be so hurtful! I'm doin' my best down here! Oh yeah, we need more lumber! Go down and tell that good for nothin' Zino to get his shredders in gear!",starts={{npcID=67535,x=0.136,y=0.558,mapID=418}},ends={{npcID=67534,x=0.204,y=0.58,mapID=418}},coords={x=0.136,y=0.558,source="quest_giver",mapID=418},questType="standard"},
[32147] = {id=32147,name="Attack Daily 06",level=15,requiredLevel=15,faction="alliance",expansion=4,questType="standard"},
[32154] = {id=32154,name="Burn Out!",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Those goblins are gettin' out of hand! First they level the forest and set up that abomination of a rig. Then, they start dumpin' their oil barrels into the bay! We got to put a stop to this madness! At the very least we need ta set them back. We need to take out their fuel supply! Maybe you'll even get to kill a few goblins in the process!",starts={{npcID=68166,x=0.168,y=0.786,mapID=418}},ends={{npcID=68166,x=0.168,y=0.786,mapID=418}},coords={x=0.168,y=0.786,source="quest_giver",mapID=418},questType="standard"},
[32155] = {id=32155,name="Necessary Breaks",level=1,requiredLevel=1,faction="alliance",expansion=4,description="It goes against me nature to break things on purpose, but in this case it's necessary. That rig the goblins are usin' is held together by a wish an' some bubblegum. We need to exploit the situation a little more. We have some saboteurs down there already, but we can use someone of your expertise to hurry the job along. Get down there an' start breakin' and stealin' some valves!",questType="standard"},
[32159] = {id=32159,name="Circle of Life",level=1,requiredLevel=1,faction="alliance",expansion=4,description="We should attempt to offset the destruction being wrought on this continent as much as possible. For every tree they destroy, we will plant a new one! Take these seeds and begin the regrowth process, . Do not linger for too long though. Nature is unpredictable, and no doubt the anger and hate exuding from Domination Point has seeped into the ground. I cannot guarantee that the plant that springs from these seeds will not be hostile.",questType="standard"},
[32173] = {id=32173,name="Build Portal 01",level=15,requiredLevel=15,faction="horde",expansion=4,questType="standard"},
[32174] = {id=32174,name="Build Portal 01",level=15,requiredLevel=15,faction="alliance",expansion=4,questType="standard"},
[32195] = {id=32195,name="Anger Remains",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="From the looks o' our initial survey, this entire area is humming with residual sha energy. You know what ta do, . Destroy any last traces ye can find o' the stuff!",questType="standard"},
[32200] = {id=32200,name="Dangers of Za'Tual",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6716,description=", what I ask of you is little short of genocide, but it is a task that must be done. Find trolls within their town or on the beach and slay them, for the good of us all.",starts={{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=70520,x=0.368,y=0.648,mapID=504}},coords={x=0.368,y=0.648,source="quest_giver",zoneID=6507},questType="standard"},
[32201] = {id=32201,name="Grave Circumstances",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder. If our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position. They must be eliminated.",starts={{npcID=67989,x=0.384,y=0.512,mapID=504}},ends={{npcID=67989,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32205] = {id=32205,name="Gather Scout Reports",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32206] = {id=32206,name="This Just Won't Do",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6677,description="The Zandalari here are very powerful, . They should not be underestimated. We cannot afford to ignore them as a threat simply because they do not wield swords. More arrive every day, and with them centuries of magic knowledge. This threat must be dealt with, and quickly. Aid us in clearing this area, . Perhaps we can even learn something from them in the process.",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",zoneID=6507},questType="standard"},
[32207] = {id=32207,name="Saur Loser",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6716,description="Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry. We need you to kill any Zandalari you find in there before they can get their mounted monstrosities out into the open battlefield.",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},ends={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",zoneID=6507},questType="standard"},
[32208] = {id=32208,name="Maximum Capacitor",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The mines north of here are being used to extract Ghost Iron ore and energize it with lightning energy. We need to destroy the drills they use to extract the ore. They are impervious to normal attack, but can be overloaded using the proper methods. Oh - and while you're there, take out whoever is running the operation.",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32209] = {id=32209,name="Save Our Scouts!",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The heavy mogu presence in the mines let us know it was a place of great importance - but we needed to gather more information on their activities there, so we sent agents into the mines to spy on them. Unfortunately, many were captured, and we've found that some are being tortured in the mines. You have to go rescue them - nobody deserves what they are going through... And, when you finish, kill whoever captured them. No mercy, $p!",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32210] = {id=32210,name="Kill mogu boss for key, use object behind jumping puzzle",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32212] = {id=32212,name="The Assault on Zeb'tula",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6677,description="Our scouting efforts along the coast have given us valuable intelligence about the island, . However, we will accomplish nothing if we do not advance forward onto the mainland. I have assembled a team of our most elite aerial units to begin the attack. I would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment. When you are ready to begin the attack, speak to me.",starts={{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70371,x=0.284,y=0.522,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.326,y=0.354,source="quest_giver",zoneID=6507},questType="standard"},
[32213] = {id=32213,name="Old Enemies",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=5842,mapID=388,description="So Jaina and the Kirin Tor think they can push us out again? I will not stand by and allow them to repeat the events of Dalaran! This time we fight back! This time we do the pushing... Go to Violet Rise and slay any Kirin Tor agent you find.",starts={{npcID=67990,x=0.326,y=0.354,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.326,y=0.354,source="quest_giver",mapID=388},questType="pvp"},
[32215] = {id=32215,name="Heinous Sacrifice",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari perform heinous rites against our people! They must be stopped! Delve into the heart of the Za'Tual and destroy their altars.",starts={{npcID=69418,x=0.366,y=0.646,mapID=504}},ends={{npcID=69418,x=0.366,y=0.646,mapID=504}},coords={x=0.366,y=0.646,source="quest_giver",mapID=504},questType="standard"},
[32216] = {id=32216,name="Pterrible Ptorment",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari treat their skyscreamer pets as little more than scuttling vermin, bending them to their will with violence and torment. I can hear one writhing in pain at their hands. Find the tormented skyscreamer within Za'Tual and help it break free of its captors.",starts={{npcID=67984,x=0.368,y=0.648,mapID=504}},ends={{npcID=67984,x=0.368,y=0.648,mapID=504}},coords={x=0.368,y=0.648,source="quest_giver",mapID=504},questType="standard"},
[32217] = {id=32217,name="Dark Offerings",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The spirtibinders of the Zandalari perform sacrificial rites to appease the loa and their vile gods. These dark rituals involve the sacrifice of our people. Destroy any offerings you can find among their tents in Za'Tual and perhaps we can stall the sacrifices.",starts={{npcID=69418,x=0.366,y=0.646,mapID=504}},ends={{npcID=69418,x=0.366,y=0.646,mapID=504}},coords={x=0.366,y=0.646,source="quest_giver",mapID=504},questType="standard"},
[32218] = {id=32218,name="Ashes of the Enemy",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The mogu here at the Court of Bones are bolstering their army by resurrecting the spirits of their dead. We cannot allow them to revive their fallen warriors. Take this torch and burn any mummified corpses that you can find. We will destroy our enemies before they have a chance to rise.",starts={{npcID=67983,x=0.384,y=0.512,mapID=504}},ends={{npcID=67983,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32219] = {id=32219,name="Stone Cold",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Our assault on the Court of Bones continues. Our progress remains slow, but measurable. Unfortunately, we've received several reports of stone quilen statues coming to life without warning. I can't have these quilen threatening my research expedition. Venture into the Court of Bones and destroy any quilen statues that you can find.",starts={{npcID=69389,x=0.384,y=0.512,mapID=504}},ends={{npcID=69389,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32220] = {id=32220,name="Soul Surrender",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals. The mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war. Horde or Alliance, it matters not. We cannot allow the mogu to bolster their numbers. Go into the crypts. Free any prisoners that are still living.",starts={{npcID=67983,x=0.384,y=0.512,mapID=504}},ends={{npcID=67989,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32224] = {id=32224,name="Rise No More!",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Have you seen the ghosts wandering the graveyard? They are risen ancestors , the spirits of slain mogu who have been called back to this world. When angered, they attack swiftly and silently, and their numbers increase by the day. They do not belong here. Destroy them, and send them back beyond the grave.",starts={{npcID=69389,x=0.384,y=0.512,mapID=504}},ends={{npcID=69389,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32225] = {id=32225,name="The Call of Thunder",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity. We suspect that this weapon is meant to rain destruction on our stronghold at Dawnseeker Promontory. There is no time to delay. You must stop their ritual at once.",starts={{npcID=67989,x=0.384,y=0.512,mapID=504}},ends={{npcID=67989,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32226] = {id=32226,name="Into the Crypts",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Reliquary is having a field day out here, literally! Every day, the researchers find more relics to study and catalog. Recently, one of our adventurers found this scroll at the Court of Bones. I believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted. Would you be willing to test out my theory?",starts={{npcID=69389,x=0.384,y=0.512,mapID=504}},ends={{npcID=69389,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32227] = {id=32227,name="Preventing a Future Threat",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The creatures the Zandalari ride don't start out so big, nor do they start out the vicious and loyal creatures they become. If you can frighten some of the hatchling skyscreamers away from the beach, perhaps they will have a chance at a real life.",starts={{npcID=67984,x=0.368,y=0.648,mapID=504}},ends={{npcID=67984,x=0.368,y=0.648,mapID=504}},coords={x=0.368,y=0.648,source="quest_giver",mapID=504},questType="standard"},
[32229] = {id=32229,name="Kill Roaming Troll War Party",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32230] = {id=32230,name="The Zandalari Colossus",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, .",starts={{npcID=67673,x=0.324,y=0.352,mapID=504}},ends={{npcID=67673,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="standard"},
[32232] = {id=32232,name="What's Inside Counts",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="I noticed something strange on my last scouting mission. A group of Zandalari are performing a ritual on what appears to be a very large sentry. They may be trying to re-animate it. We need that ritual stopped and the sentry destroyed. Anything that large can't be good. I've sent a scout ahead to observe their actions. Meet with her and figure out how to stop them.",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32233] = {id=32233,name="Very Disarming",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6757,mapID=554,description="Look around you, . What do you see? I see an opportunity. The casters here work to imbue the Zandalari weapons with powerful magic. As if a sharp blade isn't enough to cut even the strongest foe down to size. In my scouting I've noticed the weapons are not very well guarded. This is where you come in... If we can steal a few of these weapons we may be able to use them. At the very least they are out of enemy hands.",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=554},questType="standard"},
[32234] = {id=32234,name="Knowledge Is Power",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari here practice a different kind of magic. We must understand it before we can defeat it, . Their control over the arcane and shadow is impressive. I wish to learn how they have achieved what so many others have not. I believe their ritual artifacts may hold the answers I seek. Bring me a sampling of the artifacts you find, and I will ensure you are rewarded properly.",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},ends={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32237] = {id=32237,name="Precious Resource",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="What we have here is too much of a good thing, ! Our rig just can't handle the amount of oil we're pumping out of the ground. It's literally bursting at the seams! To be more accurate, it's bursting at the valves. I've been working double-time to get the valves repaired, but every time I finish the rounds, they're all broken again. It's as if someone is following me... That's ridiculous though.... Maybe you'll have better luck. Try getting as many of those valves tightened as you can.",starts={{npcID=67553,x=0.252,y=0.604,mapID=418}},ends={{npcID=67553,x=0.252,y=0.604,mapID=418}},coords={x=0.252,y=0.604,source="quest_giver",mapID=418},questType="standard"},
[32247] = {id=32247,name="A King Among Men",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="There's no time to waste, we need to find Troteman and secure the beach. We should check on the dwarves, too - the Explorers' League is tough, but they're no army. They should be along the cliff just north of here. Let us ride, . For our friends. For the Alliance.",starts={{npcID=68392,x=0.852,y=0.29,mapID=418}},coords={x=0.852,y=0.29,source="quest_giver",mapID=418},questType="standard"},
[32252] = {id=32252,name="Harbingers of the Loa",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Have you heard of the loa? We do not understand all of what it is, but it seems to be a dark magic with some degree of sentience. We do not know what power the loa might possess, but I must ask you to put a stop to their rituals, .",starts={{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=70520,x=0.368,y=0.648,mapID=504}},coords={x=0.368,y=0.648,source="quest_giver",mapID=504},questType="standard"},
[32254] = {id=32254,name="Manipulating the Saurok",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance. They will be concealed from view. Look for shimmering columns of light within the saurok village.",starts={{npcID=67660,x=0.468,y=0.668,mapID=504}},ends={{npcID=67660,x=0.468,y=0.668,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32258] = {id=32258,name="Horde Quest Choice: PvP",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32259] = {id=32259,name="Horde Quest Choice: PvE",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32260] = {id=32260,name="Alliance Quest Choice: PvE",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32261] = {id=32261,name="Alliance Quest Choice: PvP",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32262] = {id=32262,name="Captive Audience",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Kirin Tor have gone too far! Now they hold our fellow Sunreavers as war prisoners! There will be no discussion of prisoner exchange. We will handle this ourselves. Go to Violet Rise and free as many prisoners as you can. Do not get captured yourself. We cannot afford to lose you too.",starts={{npcID=67663,x=0.324,y=0.352,mapID=504}},ends={{npcID=67663,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32264] = {id=32264,name="Spellbound",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Jaina possesses several very powerful magic artifacts. These items travel with her at all times, and are never far from her grasp. I have an interest in one of these items. A tome, filled with knowledge, passed from one archmage to another. I have only ever seen glimpses of it. Now that we fight on opposite sides I see no issue in removing the tome from her possession.",starts={{npcID=67662,x=0.334,y=0.35,mapID=504}},ends={{npcID=67662,x=0.334,y=0.35,mapID=504}},coords={x=0.334,y=0.35,source="quest_giver",mapID=504},questType="pvp"},
[32265] = {id=32265,name="Charged Moganite",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We have been dispatching spies into the Kirin Tor base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here. They have not returned, and I can confirm they have left the Kirin Tor base. Search the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.",starts={{npcID=67662,x=0.334,y=0.35,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504}},ends={{npcID=67662,x=0.334,y=0.35,mapID=504}},coords={x=0.334,y=0.35,source="quest_giver",mapID=504},questType="pvp"},
[32266] = {id=32266,name="Mana Manifestations",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Manafiends are nasty creatures. Small and easy to underestimate, but deadly to our magic casters. The Kirin Tor have these pests crawling all over Violet Rise. We will need to handle them carefully. Alone they are easily managed, but in groups they become a different challenge altogether. Go to Violet Rise and cut down their numbers.",starts={{npcID=67673,x=0.324,y=0.352,mapID=504}},ends={{npcID=67673,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32268] = {id=32268,name="Tactical Mana Bombs",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Ah, $p, just the I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Violet Rise to the southeast. Here, take these. I do not trust our standard soldiers with such firepower. Oh... and don't shake them, whatever you do. Plant one of the Kirin Tor ships, another one near their supplies, and the last on the construct they are building.",starts={{npcID=67673,x=0.324,y=0.352,mapID=504}},ends={{npcID=67673,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32269] = {id=32269,name="Breaking Down the Defenses",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We need to keep a close watch on the Kirin Tor and their day-to-day activities. Normally this would be easy. We would sneak in a spy and have them report back to us. However, we've run into a slight problem I believe you can help us with. The Kirin Tor perimeter wards have increased in power. It's next to impossible to get someone past their lines. If they were disabled we might be able to sneak in before they can be repaired.",starts={{npcID=67673,x=0.324,y=0.352,mapID=504}},ends={{npcID=67673,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32274] = {id=32274,name="The Residents of Ihgaluk",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction. A more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.",starts={{npcID=69425,x=0.468,y=0.668,mapID=504}},ends={{npcID=69425,x=0.468,y=0.668,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32275] = {id=32275,name="Surgical Death",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6677,description="The Zandalari train skyscreamers to become ferocious beasts in the skies. The spiritbinders require endless sacrifices - of our people - to be brought to them. And, the jaguar warriors venture ever closer toward the heart of our camp. Find them in Za'Tual and remove the threat.",starts={{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=70520,x=0.368,y=0.648,mapID=504}},coords={x=0.368,y=0.648,source="quest_giver",zoneID=6507},questType="standard"},
[32276] = {id=32276,name="Tear Down This Wall!",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6677,description="The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon. I suppose we'll have to make a gate of our own then. Let me know when you're ready, .",starts={{npcID=67990,x=0.326,y=0.354,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.326,y=0.354,source="quest_giver",zoneID=6507},questType="standard"},
[32277] = {id=32277,name="To the Skies!",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6677,description="We can use the pterrorwing that you found to strike a decisive blow against the mogu. Their mining operation is vulnerable to attack from the air, and your pterrorwing is the only beast we have capable of flying out there. Let me know when you are ready!",starts={{npcID=67990,x=0.326,y=0.354,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=69742,x=0.328,y=0.326,mapID=504}},coords={x=0.326,y=0.354,source="quest_giver",zoneID=6507},questType="standard"},
[32282] = {id=32282,name="Compy Stomp",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The raptors and compies of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares. I need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32283] = {id=32283,name="Loa-saur",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers. We need to put a stop to this. Search the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts. We must not allow these atrocities to continue.",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},ends={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32285] = {id=32285,name="The Sleepless Legion",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.",starts={{npcID=67662,x=0.334,y=0.35,mapID=504}},ends={{npcID=67662,x=0.334,y=0.35,mapID=504}},coords={x=0.334,y=0.35,source="quest_giver",mapID=504},questType="standard"},
[32286] = {id=32286,name="Kill Mogu Blood-seekers (Roaming pairs, actively fighting scouts, and performing rituals on corpses)",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32287] = {id=32287,name="Enemies Beneath the Tower",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6716,description="There are mogu in the Diremoor animating the army of statues near the tower. Lor'themar wants them dead. I think you're the one to do it.",starts={{npcID=67662,x=0.334,y=0.35,mapID=504}},ends={{npcID=67662,x=0.334,y=0.35,mapID=504}},coords={x=0.334,y=0.35,source="quest_giver",zoneID=6507},questType="standard"},
[32288] = {id=32288,name="Bolstering the Defenses",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="This island holds many dangers for us. Threats loom from every side. We must defend our hold on these shores at all costs. Perimeter wards have been placed around Dawnseeker Promontory. By default they will inflict damage, but are not fatal in their attack. Now is not the time to be merciful, . The perimeter wards need to be deadly! Go and empower the perimeter wards surrounding our camp.",starts={{npcID=67663,x=0.324,y=0.352,mapID=504}},ends={{npcID=67663,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32292] = {id=32292,name="Forge Ahead!",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability. And beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city. It's time to move out!",ends={{npcID=70551,x=0.586,y=0.426,mapID=504}},questType="standard"},
[32293] = {id=32293,name="Among the Bones",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="My scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. I need someone capable to see him dispatched. Are you up to the task?",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32294] = {id=32294,name="Raining Bones",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp. Would you be willing to do the deed?",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32295] = {id=32295,name="An Unusual Tome",level=35,requiredLevel=35,faction="none",expansion=4,description="The tome appears to be written in an ornate, sprawling script that seems to rise off the pages. It vaguely resembles Demonic, but the symbols are far more elaborate than any you've ever seen. Perhaps one of your demonic companions can tell you more.",questType="standard"},
[32297] = {id=32297,name="Direhorn or Devilsaur",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process. Within these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms. Go into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},ends={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32298] = {id=32298,name="Dino Might",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts. Two can play at that game. I want you to find some of these fetishes and try them out on the various beasts in the Beast Pens. Take careful note of how each beast responds to each fetish. Then report your results to me. Maybe this will give us the edge we need against the Zandalari.",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32299] = {id=32299,name="Just Some Light Clean-Up Work",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="This is not a glamorous job. Let me put it to you bluntly. The Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter. The saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.",starts={{npcID=69371,x=0.468,y=0.668,mapID=504}},ends={{npcID=69371,x=0.468,y=0.668,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32300] = {id=32300,name="Disarming Irony",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Well, it would seem the Lady Proudmoore has decided to use our own weaponry against us. Our perimeter wards reported several spies slipping through our defenses carrying tactical mana bombs . I would enjoy the irony if these bombs were less dangerous. Search for these bombs and disarm them. Our wards reported one near the horde ships to the north, one on a bridge to the main isle, and one near our scrying crystals on the eastern side of the Promontory.",starts={{npcID=67663,x=0.324,y=0.352,mapID=504}},ends={{npcID=67663,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32301] = {id=32301,name="Old Enemies",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=5842,mapID=388,description="To think, we were once on the same side! The Sunreavers' treachery caught us all off guard. Never again! They have shown their true natures to us. Siding with Garrosh and his madness has marked them all for death. Kill any agent of the Sunreavers that you find. We will show them no mercy here.",starts={{npcID=67993,x=0.632,y=0.722,mapID=504}},ends={{npcID=67993,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=388},questType="pvp"},
[32302] = {id=32302,name="Desconstruction",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Kirin Tor constructs are primitive at best. Nevertheless, they pose a threat. Go to Violet Rise and dismantle Jaina's pitiful war machines. Show the Kirin Tor how easily they can be defeated! This will be a message the Kirin Tor cannot easily ignore.",starts={{npcID=67673,x=0.324,y=0.352,mapID=504}},ends={{npcID=67673,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32303] = {id=32303,name="Made for War",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Jaina thinks this battle will be easily won. I intend to show her how wrong she is! The Kirin Tor brought a weapon with them that must be destroyed. The Arcane Destroyer is a large construct capable of turning the tides of war in their favor. Destroying this monstrosity would send a very clear message to Proudmoore.",starts={{npcID=67662,x=0.334,y=0.35,mapID=504}},ends={{npcID=67662,x=0.334,y=0.35,mapID=504}},coords={x=0.334,y=0.35,source="quest_giver",mapID=504},questType="pvp"},
[32304] = {id=32304,name="High Recognition",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,starts={{npcID=67990,x=0.326,y=0.354,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.326,y=0.354,source="quest_giver",mapID=504},questType="pvp"},
[32305] = {id=32305,name="Overpowered",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Kirin Tor are using mana foci to empower their forces. We cannot allow this to continue. You'll find these foci scattered around the outskirts of Violet Rise. Use this mana crystal to destroy as many as you can. Each mana focus we destroy is another small victory for our cause.",starts={{npcID=67663,x=0.324,y=0.352,mapID=504}},ends={{npcID=67663,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="pvp"},
[32316] = {id=32316,name="Heart Of The Alliance",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6142,description="I can't believe this has happened, . After all we have been through here on Pandaria, will our people never learn from their past mistakes? Brann's expedition returned recently from Mogujia, bearing a sample of sha for study. I had my reservations about this endeavor in the first place, and my worst fears have been realized. The sha has escaped containment. I do not need to explain the horror of bringing the sha into the heart of the Vale. We must dispel any sha we can find, and quickly!",starts={{npcID=67948,x=0.332,y=0.26,mapID=379}},coords={x=0.332,y=0.26,source="quest_giver",zoneID=5841},questType="standard"},
[32321] = {id=32321,name="The Monkey King",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Ever since the Horde captured the Divine Bell I have been searching for a means to counter its power. My research got as far as this tomb. I am going inside. If you follow me, I will share the rest as we go. If we get separated, meet me back here at the entrance to the tomb. Speak to me when you are ready to proceed.",starts={{npcID=68004,x=0.53,y=0.464,mapID=379},{npcID=68004,x=0.89,y=0.318,mapID=418}},ends={{npcID=68003,x=0.488,y=0.504,mapID=379}},coords={x=0.53,y=0.464,source="quest_giver",mapID=418},questType="standard"},
[32324] = {id=32324,name="Seek the Signal",level=35,requiredLevel=35,faction="none",expansion=4,description="The soulstone shards fuse together easily in your hands. Strangely, no soul is stored within the stone. Instead, the stone seems to be drawing power from somewhere in Shadowmoon Valley. Looking east, you feel the power linked beyond the mountains, to the very gates of the Black Temple.",questType="standard"},
[32325] = {id=32325,name="Infiltrating the Black Temple",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6613,description="It's clear that Jubeka's soulstone has lead you here to the Black Temple. The question remains... why? The only remaining option is to head inside and figure out why they were here.",questType="standard"},
[32334] = {id=32334,name="The Third Riddle: Strength",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="The mallet you seek is not a toy for children, It calls trouble like the song of a siren. A test of strength the Monkey King will require, Before you receive this tool of your desire. At the Temple of the White Tiger you will find A challenger to test how well you are resigned Step through the main door and then turn right down the ramp Challenge the ook waiting for you there like a champ!",starts={{npcID=68003,x=0.488,y=0.504,mapID=379}},ends={{npcID=68538,x=0.89,y=0.318,mapID=418}},coords={x=0.488,y=0.504,source="quest_giver",mapID=418},questType="standard"},
[32339] = {id=32339,name="Rebuilding the Mallet (Tracker)",level=1,requiredLevel=1,faction="both",expansion=4,description="Time for the fixing and then time for the mixing!",questType="standard"},
[32340] = {id=32340,name="Plunder the Black Temple",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6613,description="While Akama and his men are dealing with the demons, there is nobody to stop you from stealing a relic or two...",questType="standard"},
[32341] = {id=32341,name="Demonstrate Your Power",level=35,requiredLevel=35,faction="none",expansion=4,zoneID=6613,description="Akama and his men are under siege by the forces you unleashed in the Reliquary of Souls. Demonstrate your power to Akama by saving his men from the demonic forces!",questType="standard"},
[32348] = {id=32348,name="Kick 'em While They're Down",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6609,description="The Alliance may think they have a stranglehold on the ruins, given that their base of operations is close. We're going to disabuse them of that notion. Go take out some of their guards.",questType="standard"},
[32351] = {id=32351,name="Echoes of Thunder",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5841,mapID=379,description="Ah, , we meet again. I have heard some wondrous news. High Chieftain Baine Bloodhoof of the tauren has arrived here on Pandaria. He meets with Warchief Garrosh Hellscream and Regent Lord Lor'themar Theron now, at the Shrine of Two Moons in the Vale of Eternal Blossoms. He sent me a strange request - to send him a loyal champion of the Horde, capable of combat... and discretion. I can think of none better to send than you. Speak to Tak-Tak if you seek transport.",starts={{npcID=67939,x=0.104,y=0.538,mapID=418}},ends={{npcID=68287,x=0.604,y=0.552,mapID=379}},coords={x=0.104,y=0.538,source="quest_giver",mapID=379},questType="standard"},
[32355] = {id=32355,name="The Harmonic Mallet",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="$p! Prince Anduin has somehow slipped his guards again. His control over the light is greatly increasing. He was last seen heading to Kun-Lai Summit. He gave our mages the slip around the Valley of Emperors. Can you find him? He insists on searching for what he claims is a counter to the Divine Bell. Perhaps you can talk some sense into him before he seizes control of your mind and has you dance your way back here. Talk to Fennie for a ride into the mountains.",starts={{npcID=67940,x=0.894,y=0.326,mapID=418}},ends={{npcID=68004,x=0.89,y=0.318,mapID=418},{npcID=68004,x=0.53,y=0.464,mapID=379}},coords={x=0.894,y=0.326,source="quest_giver",mapID=379},questType="standard"},
[32356] = {id=32356,name="Tracking Event: Ambassadors Summoned",level=0,requiredLevel=0,faction="alliance",expansion=4,description="It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly. I'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.",questType="standard"},
[32357] = {id=32357,name="Tracking Event: Event Complete",level=0,requiredLevel=0,faction="alliance",expansion=4,description="It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly. I'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.",questType="standard"},
[32358] = {id=32358,name="The Soulcore",level=35,requiredLevel=35,faction="none",expansion=4,zoneID=6613,questType="standard"},
[32359] = {id=32359,name="The Eye of the Naaru",level=35,requiredLevel=35,faction="none",expansion=4,description="The soulcore has transformed into a crystal. This is clearly the artifact that Kanrethad and Jubeka were attempting to create, but you still have no idea where they went. Seek out the Black Prince in the Tavern of the Mists and see if you can acquire some information on where they went.",questType="standard"},
[32361] = {id=32361,name="Tracking Event: Event Complete",level=0,requiredLevel=0,faction="horde",expansion=4,description="It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly. I'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.",questType="standard"},
[32362] = {id=32362,name="The Fate of Dalaran",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=4395,mapID=118,description="Jaina is refusing to hear me out. Father was hoping I would have some pull with her, but I think she still sees me as a child. You, on the other hand, are a hero of the Alliance and I know she respects your deeds. Is there something you can say to her to convince her we need her help?",questType="standard"},
[32363] = {id=32363,name="The Kun-Lai Expedition",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5841,mapID=379,description="I have another message for you from High Chieftain Bloodhoof. It seems you've made quite the impression on him. He travels with the Warchief's vanguard into Kun-Lai Summit, to the north. They have set up an outpost, Garrosh'ar Advance, just east of One Keg. You had best not keep him waiting. Speak to Tak-Tak for swift travel.",starts={{npcID=67939,x=0.104,y=0.538,mapID=418}},ends={{npcID=68287,x=0.604,y=0.552,mapID=379}},coords={x=0.104,y=0.538,source="quest_giver",mapID=379},questType="standard"},
[32364] = {id=32364,name="Pandaren Medicine",level=15,requiredLevel=15,faction="horde",expansion=4,description="While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien. I am needed here, so I have no choice but to ask you to find the ingredients for me. The recipe can be found in a book near my other things, just behind me.",questType="standard"},
[32368] = {id=32368,name="Memory Wine",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5841,mapID=379,description="The tincture is ready. Now, drink.",starts={{npcID=68287,x=0.604,y=0.552,mapID=379}},ends={{npcID=68287,x=0.604,y=0.552,mapID=379}},coords={x=0.604,y=0.552,source="quest_giver",mapID=379},questType="standard"},
[32369] = {id=32369,name="Secrets of the Past",level=1,requiredLevel=1,faction="horde",expansion=4,questType="standard"},
[32372] = {id=32372,name="De-Subjugation",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6453,mapID=463,description="The Kor'kron have been trained to be the finest, most loyal soldiers of the Warchief. Their presence here means that Garrosh fears an uprising. Vol'jin and his people are as much a part of the Horde as any orc. We must break this occupation and free the trolls. It pains me to say this, but you must eliminate enough of the Kor'kron so that the trolls can retake their city. Then meet me at Darkspear Hold so we might challenge their officer directly.",starts={{npcID=68025,x=0.444,y=0.666,mapID=1},{npcID=68025,x=0.384,y=0.466,mapID=463}},ends={{npcID=68025,x=0.444,y=0.666,mapID=1},{npcID=68025,x=0.384,y=0.466,mapID=463}},coords={x=0.444,y=0.666,source="quest_giver",mapID=463},questType="standard"},
[32375] = {id=32375,name="A Dash of That",level=15,requiredLevel=15,faction="horde",expansion=4,description="100 Buttonbelly Mushrooms . Must be freshly harvested from a wet, dark place. Fungus is very good for the health! (Or it might kill you, cause serious illness, rash, hallucination, or loosen bowels. Note to self - MUST be careful when selecting wild mushrooms!)",questType="standard"},
[32383] = {id=32383,name="Bugging Out",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5841,mapID=379,description="I've managed to plant a few bugs around the camp, but there could always be more. I disguised the bugs to look like statues. They blend in perfectly with the other artifacts lying around. Your disguise should allow you to move freely around the camp. Just don't go near the dog and don't linger around Garrosh! Nero and Garrosh will see through your disguise. If you get caught I can't help you. I can't compromise the mission!",starts={{npcID=68417,x=0.592,y=0.842,mapID=379}},ends={{npcID=68417,x=0.592,y=0.842,mapID=379}},coords={x=0.592,y=0.842,source="quest_giver",mapID=379},questType="standard"},
[32426] = {id=32426,name="Stirred, Not Shaken",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=2257,mapID=500,description="Alright, I'll tell you how to find Connelly. Agent Connelly is currently posing as the high roller, Professor Kilt . He spends most of his time in the Boom Room. Rumor has it he's after one of the fighters for some long forgotten betrayal. Unfortunately, the lounge is by invitation only. Lucky for you I just happen to have an invitation. Try not to look too obvious when you walk past the bouncers. If you get caught you didn't get this pass from me. In fact you and I have never met!",questType="standard"},
[32428] = {id=32428,name="Pandaren Spirit Tamer",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5841,mapID=379,description="Legend tells of legendary pandaren spirits that roam the lands of Pandaria. Find them and defeat them in a pet battle.",starts={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},ends={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},coords={x=0.864,y=0.6,source="quest_giver",mapID=379},questType="standard"},
[32433] = {id=32433,name="Undermining the Under Miner",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Grezik Oregrind has become a nuisance that must be eliminated. This land responds to all of our actions as I am sure you are aware, . Because of this, we cannot allow the goblins to haphazardly destroy it. Our scouts have reported Sha emerging from Oregrind's Dig. The brains behind the operation is a goblin named Grezik Oregrind . Destroy him and perhaps we will stall the operation just long enough to contain the Sha.",questType="standard"},
[32434] = {id=32434,name="Burning Pandaren Spirit",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5842,mapID=388,description="You're back! Up for another battle with me?",starts={{npcID=68463,x=0.57,y=0.422,mapID=388}},ends={{npcID=68463,x=0.57,y=0.422,mapID=388}},coords={x=0.57,y=0.422,source="quest_giver",mapID=388},questType="standard"},
[32439] = {id=32439,name="Flowing Pandaren Spirit",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6138,mapID=422,description="You're back! Up for another battle with me?",starts={{npcID=68462,x=0.612,y=0.876,mapID=422}},ends={{npcID=68462,x=0.612,y=0.876,mapID=422}},coords={x=0.612,y=0.876,source="quest_giver",mapID=422},questType="standard"},
[32440] = {id=32440,name="Whispering Pandaren Spirit",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5785,mapID=371,description="You're back! Up for another battle with me?",starts={{npcID=68464,x=0.288,y=0.36,mapID=371}},ends={{npcID=68464,x=0.288,y=0.36,mapID=371}},coords={x=0.288,y=0.36,source="quest_giver",mapID=371},questType="standard"},
[32441] = {id=32441,name="Thundering Pandaren Spirit",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5841,mapID=379,description="You're back! Up for another battle with me?",starts={{npcID=68465,x=0.648,y=0.936,mapID=379}},ends={{npcID=68465,x=0.648,y=0.936,mapID=379}},coords={x=0.648,y=0.936,source="quest_giver",mapID=379},questType="standard"},
[32444] = {id=32444,name="FLAG - Earned Brawler Title (Weekly)",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6138,mapID=422,questType="standard"},
[32451] = {id=32451,name="Send A Message",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="It's time we show these Horde mongrels the full strength of the Alliance! Today we bring the battle to their door. Report to Admiral Rogers aboard the Skyfire. She will have further instructions. Good luck out there, . Do the Alliance proud!",starts={{npcID=68908,x=0.898,y=0.324,mapID=418}},ends={{npcID=67386,x=0.164,y=0.792,mapID=418}},coords={x=0.898,y=0.324,source="quest_giver",mapID=418},questType="standard"},
[32452] = {id=32452,name="And Then There Were Goblins",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="We're fighting a war on all fronts, . Even Pandaria itself needs our protection. The Bilgewater goblins are destroying land that doesn't belong to them. They must be stopped! Report to Sky Admiral Rogers aboard the Skyfire. From her vantage point she should have a good idea of where their weak spots are.",starts={{npcID=68908,x=0.898,y=0.324,mapID=418}},ends={{npcID=67386,x=0.164,y=0.792,mapID=418}},coords={x=0.898,y=0.324,source="quest_giver",mapID=418},questType="standard"},
[32455] = {id=32455,name="The Silence",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="D..did we... do it? L..look... in.. my... bag... Use... flare...",starts={{npcID=68987,x=0.56,y=0.318,mapID=379},{npcID=68987,x=0.878,y=0.328,mapID=418}},ends={{npcID=69090,x=0.876,y=0.33,mapID=418}},coords={x=0.56,y=0.318,source="quest_giver",mapID=418},questType="standard"},
[32459] = {id=32459,name="With the Wind's Blessing...",level=15,requiredLevel=15,faction="horde",expansion=4,questType="standard"},
[32460] = {id=32460,name="Tracking the Thieves",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=1657,mapID=89,description="We WILL get to the bottom of this. , you're coming with me. We'll search every inch of this city if we have to, but we'll find out how they took the bell... and where. I'm picking up traces of arcane magic here... we need to follow the trail!",starts={{npcID=68651,x=0.4,y=0.504,mapID=57},{npcID=68651,x=0.39,y=0.328,mapID=89}},ends={{npcID=68651,x=0.4,y=0.504,mapID=57},{npcID=68651,x=0.39,y=0.328,mapID=89}},coords={x=0.4,y=0.504,source="quest_giver",mapID=89},questType="standard"},
[32461] = {id=32461,name="The Order of the Cloud Serpent",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Ahhh, it seems you have found yourself the proud owner of a majestic cloud serpent. Before you may fly the skies on this powerful creature, you must first earn the skill to ride it. The Order of the Cloud Serpent can teach you the knowledge that you seek. If you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest . I wish you luck, .",ends={{npcID=58228,x=0.574,y=0.45,mapID=371}},questType="standard"},
[32467] = {id=32467,name="Sacrificial Prevention [PH]",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,description="The Zandalari Priests in the town to the north prepare the bodies of our fallen allies for sacrifice. The best way to prevent this from happening? Kill them. Kill them all.",questType="standard"},
[32472] = {id=32472,name="Frighten Pterodactyls [PH]",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,description="The Pterodactyl Hatchlings being trained by Zandalari to the north are not yet the violent and savage beasts they are to become. I believe we should save these creatures before the trolls corrupt them. If you could just frighten them off, perhaps some of them will be spared an unfortunate fate.",questType="standard"},
[32475] = {id=32475,name="A Spark of Life",level=32,requiredLevel=32,faction="none",expansion=4,zoneID=6507,mapID=504,description="The Thunder-Laced Egg burns your hand as you hold it. You recall that Yalia Sagewhisper of the Shado-Pan discussing the history of the Thundering Cloud Serpents, perhaps she will know what to do with it.",questType="standard"},
[32485] = {id=32485,name="Bolstering the Defenses",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="This island is a dangerous place, . We have to worry about attacks from the Zandalari, mogu, saurok, and worst of all the Sunreavers. I had perimeter wards placed on the outskirts of our camp for additional protection. In their current state they will only injure an attacker, but I'm done with warnings! With your help we can super-charge the wards into a more deadly defense system.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32489] = {id=32489,name="The Creeping Carpet of Ihgaluk",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Ah, roaches! I once bought a pet roach in the Undercity. Roaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far. Ihgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.",starts={{npcID=69371,x=0.468,y=0.668,mapID=504}},ends={{npcID=69371,x=0.468,y=0.668,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32492] = {id=32492,name="Destroy Cauldrons",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32493] = {id=32493,name="They All Fall Down",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6677,description="The Zandalari do not tolerate weakness in their ranks, . Those that are deemed weak are often sacrificed in barbaric ceremonies. The victims' spirits are captured and entombed within the sentries you see guarding the grounds. I wish to study their essence. For this I will need your help. Take this resonance crystal and siphon the spirits from the sentry corpses. Do not allow them to escape!",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},ends={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",zoneID=6507},questType="standard"},
[32494] = {id=32494,name="Power Play",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari have found a way to infuse items of great power with the essence of their loa. These items are often passed from one generation to another, each recipient adding to the item's power. Two such items exist here. To be specific, two masks, worn by two brothers. Spiritbinder Tu'chek and Arcanital Ra'kul must be stopped and their masks destroyed. Kill them and return their masks to me. I will make sure the masks are disposed of.",starts={{npcID=67986,x=0.472,y=0.406,mapID=504}},ends={{npcID=67986,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32495] = {id=32495,name="The Bloodletter",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="I have heard a disturbing report, . Just beyond our position, in the Court of Bone, the mogu bring captives to a general named Kaida the Bloodletter . I will spare you the details, but he thrives on torturing his victims. This monster must be stopped. If you fall to his blade, I wish you a swift death.",starts={{npcID=67989,x=0.384,y=0.512,mapID=504}},ends={{npcID=67989,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32504] = {id=32504,name="Mission: The Secrets of Stormwind",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=1519,mapID=84,questType="standard"},
[32506] = {id=32506,name="A Wing to Fly On",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="I've just received a report that another young pterrorwing has been spotted in the Diremoor. We need to recover as many of these as we can find. They may be the key to flying on this island.",starts={{npcID=67663,x=0.324,y=0.352,mapID=504}},ends={{npcID=67663,x=0.324,y=0.352,mapID=504}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="standard"},
[32517] = {id=32517,name="The Conquest of Stone",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="In the Court of Bones, the Thunder King's sorcerers perform dark rituals. To bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living. After these stone conquerors are brought to life, they will be formidable opponents on the battlefield. We must stop their ritual before these statues can be revived.",starts={{npcID=69389,x=0.384,y=0.512,mapID=504}},ends={{npcID=69389,x=0.384,y=0.512,mapID=504}},coords={x=0.384,y=0.512,source="quest_giver",mapID=504},questType="standard"},
[32518] = {id=32518,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=4,questType="standard"},
[32519] = {id=32519,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=4,questType="standard"},
[32520] = {id=32520,name="Competing Magic",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="My scouts have spotted a dangerous Zandalari just this side of Za'Tual. I need someone capable to see him dispatched. Are you up to the task?",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32521] = {id=32521,name="Encroaching Force",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="My scouts have spotted a Zandalari war party on the northern beach. I need someone capable to see him dispatched. Are you up to the task?",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32522] = {id=32522,name="Imposing Threat",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="My scouts have spotted a mogu leader under the central tower. He needs to be killed before he can mount an offensive on our position. Can you take care of this for me?",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32523] = {id=32523,name="The Beast Pens",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We need to counter the beasts the Zandalari are using to strike at our camp. I have dispatched Scout Captain Elsia to the Beast Pens along with some war mages to provide cover. Go and find her east of here near the breaches in the wall and help her trim down the cavalry and siege beasts being levied against us. They are masked, so look for the shimmers of their magical cloaking spells.",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32524] = {id=32524,name="The Beating of Troll Drums",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="Do you hear that, ? The beating of war drums in the distance. The Zandalari are preparing for us. Let's not give them the luxury of time to organize their defenses. We need to push the attack now! Report to Scout Captain Elsia within Conqueror's Terrace. She will have further orders for you.",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=67990,x=0.326,y=0.354,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32525] = {id=32525,name="Ashes of the Enemy",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The mogu at the Court of Bones are bolstering their army by resurrecting the spirits of their dead. We cannot allow them to revive their fallen warriors. Take this torch and burn any mummified corpses that you can find. We will destroy our enemies before they have a chance to rise.",starts={{npcID=69668,x=0.402,y=0.592,mapID=504}},ends={{npcID=69668,x=0.402,y=0.592,mapID=504}},coords={x=0.402,y=0.592,source="quest_giver",mapID=504},questType="standard"},
[32526] = {id=32526,name="Soul Surrender",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals. The mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war. Alliance or Horde, it matters not. We cannot allow the mogu to bolster their numbers. Go into the crypts. Free any prisoners that are still living.",starts={{npcID=67997,x=0.402,y=0.594,mapID=504}},ends={{npcID=67997,x=0.402,y=0.594,mapID=504}},coords={x=0.402,y=0.594,source="quest_giver",mapID=504},questType="standard"},
[32527] = {id=32527,name="Grave Circumstances",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder. If our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position. They must be eliminated.",starts={{npcID=67997,x=0.402,y=0.594,mapID=504}},ends={{npcID=67997,x=0.402,y=0.594,mapID=504}},coords={x=0.402,y=0.594,source="quest_giver",mapID=504},questType="standard"},
[32528] = {id=32528,name="Into the Crypts",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Every day, we uncover additional relics from the Court of Bones. Recently, we discovered this scroll amongst the gravestones in one of the deepest crypts. I believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted. Would you be willing to test out my theory?",starts={{npcID=69668,x=0.402,y=0.592,mapID=504}},ends={{npcID=69668,x=0.402,y=0.592,mapID=504}},coords={x=0.402,y=0.592,source="quest_giver",mapID=504},questType="standard"},
[32529] = {id=32529,name="The Call of Thunder",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity. We suspect that this weapon is meant to rain destruction on our stronghold at Violet Rise. There is no time to delay. You must stop their ritual at once.",starts={{npcID=69670,x=0.4,y=0.592,mapID=504}},ends={{npcID=69670,x=0.4,y=0.592,mapID=504}},coords={x=0.4,y=0.592,source="quest_giver",mapID=504},questType="standard"},
[32530] = {id=32530,name="The Bloodletter",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="I have heard a disturbing report, . Just beyond our position, in the Court of Bones, the mogu bring captives to a general named Kaida the Bloodletter . He thrives on torturing his victims. This monster must be stopped. If you fall to his blade, I wish you a swift death.",starts={{npcID=69670,x=0.4,y=0.592,mapID=504}},ends={{npcID=69670,x=0.4,y=0.592,mapID=504}},coords={x=0.4,y=0.592,source="quest_giver",mapID=504},questType="standard"},
[32531] = {id=32531,name="The Conquest of Stone",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="In the Court of Bones, the Thunder King's sorcerers perform dark rituals. To bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living. After these stone conquerors are brought to life, they will be formidable opponents on the battlefield. We must stop their ritual before these statues can be revived.",starts={{npcID=69670,x=0.4,y=0.592,mapID=504}},ends={{npcID=69670,x=0.4,y=0.592,mapID=504}},coords={x=0.4,y=0.592,source="quest_giver",mapID=504},questType="standard"},
[32532] = {id=32532,name="Rise No More!",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Have you seen the ghosts wandering the graveyard? They are risen ancestors , the spirits of slain mogu who have been called back to this world. When angered, they attack swiftly and silently, and their numbers increase by the day. They do not belong here. Destroy them, and send them back beyond the grave.",starts={{npcID=69668,x=0.402,y=0.592,mapID=504}},ends={{npcID=69668,x=0.402,y=0.592,mapID=504}},coords={x=0.402,y=0.592,source="quest_giver",mapID=504},questType="standard"},
[32533] = {id=32533,name="Stone Cold",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Our assault on the Court of Bones continues. Our progress remains slow, but measurable. Unfortunately, we've received several reports of stone quilen statues coming to life without warning. These quilen are too dangerous to ignore. Venture into the Court of Bones and destroy any quilen statues that you can find.",starts={{npcID=69668,x=0.402,y=0.592,mapID=504}},ends={{npcID=69668,x=0.402,y=0.592,mapID=504}},coords={x=0.402,y=0.592,source="quest_giver",mapID=504},questType="standard"},
[32535] = {id=32535,name="The Skumblade Threat",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations. Thin their numbers, . Once the Alliance takes full control of this island, we can look for more permanent solutions.",starts={{npcID=67996,x=0.556,y=0.744,mapID=504}},ends={{npcID=67996,x=0.556,y=0.744,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32536] = {id=32536,name="Manipulating the Saurok",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance. They will be concealed from view. Look for shimmering columns of light within the saurok village.",starts={{npcID=67996,x=0.556,y=0.744,mapID=504}},ends={{npcID=67996,x=0.556,y=0.744,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32537] = {id=32537,name="De-Constructed",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag. I want those constructs back. No slithering lizard will steal Silver Covenant property under my watch.",starts={{npcID=67996,x=0.556,y=0.744,mapID=504}},ends={{npcID=67996,x=0.556,y=0.744,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32538] = {id=32538,name="Heinous Sacrifice",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Some of the strongest of the spiritbinders perform heinous rites to their wretched gods. We've devised a method to destroy their altars, so the difficult task will be getting to each altar alive. Venture into the depths of Za'Tual and destroy their altars.",starts={{npcID=69674,x=0.422,y=0.662,mapID=504}},ends={{npcID=69674,x=0.422,y=0.662,mapID=504}},coords={x=0.422,y=0.662,source="quest_giver",mapID=504},questType="standard"},
[32539] = {id=32539,name="Dark Offerings",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Zandalari's spiritbinders perform dark sacrifices to appease their gods, killing our people in the process. Destroy any Zandalari offerings you can find in Za'Tual to help slow the pace of their dark sacrifices.",starts={{npcID=69674,x=0.422,y=0.662,mapID=504}},ends={{npcID=69674,x=0.422,y=0.662,mapID=504}},coords={x=0.422,y=0.662,source="quest_giver",mapID=504},questType="standard"},
[32540] = {id=32540,name="Harbingers of the Loa",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="If you spend some time in Za'Tual, you will likely see one of their large tents emanating a pure form of evil. Please, venture into the troll camp and put a stop to these unspeakable rituals.",starts={{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=70517,x=0.422,y=0.664,mapID=504}},coords={x=0.422,y=0.664,source="quest_giver",mapID=504},questType="standard"},
[32541] = {id=32541,name="Preventing a Future Threat",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="It pains me to think of the torture the poor skyscreamers must endure as the trolls train them to become implements of war. The hatchlings are quite fearful, and will fly away if you even get close them. Please, frighten some away before the Zandalari corrupt them.",starts={{npcID=69673,x=0.422,y=0.664,mapID=504}},ends={{npcID=69673,x=0.422,y=0.664,mapID=504}},coords={x=0.422,y=0.664,source="quest_giver",mapID=504},questType="standard"},
[32542] = {id=32542,name="Surgical Strike",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="Zandalari spiritbinders perform sacrifices to their gods, the beastcallers bend innocent skyscreamers to their will, and the jaguar warriors venture closer to us by the day. Dispose of these threats in Za'Tual, , and watch the might of the trolls weaken.",starts={{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=70517,x=0.422,y=0.664,mapID=504}},coords={x=0.422,y=0.664,source="quest_giver",zoneID=6507},questType="standard"},
[32543] = {id=32543,name="Dangers of Za'Tual",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6716,description="The Zandalari are a formidable foe - more so than many foes we've encountered in the past. But you are a formidable foe as well, . Enter Za'Tual to and show them the risks associated with opposing the likes of you.",starts={{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=70517,x=0.422,y=0.664,mapID=504}},coords={x=0.422,y=0.664,source="quest_giver",zoneID=6507},questType="standard"},
[32544] = {id=32544,name="Pterrible Ptorment",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="One of the trolls' skyscreamers in Za'Tual is undergoing a ritual of torture, its will being bent forever to serve its masters. Kill those that inflict such torment on the creature and we can only hope that it will return to the skies.",starts={{npcID=69673,x=0.422,y=0.664,mapID=504}},ends={{npcID=69673,x=0.422,y=0.664,mapID=504}},coords={x=0.422,y=0.664,source="quest_giver",mapID=504},questType="standard"},
[32545] = {id=32545,name="The Residents of Ihgaluk",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction. A more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.",starts={{npcID=69675,x=0.558,y=0.744,mapID=504}},ends={{npcID=69675,x=0.558,y=0.744,mapID=504}},coords={x=0.558,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32546] = {id=32546,name="Just Some Light Clean-Up Work",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="This is not a glamorous job. Let me put it to you bluntly. The Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter. The saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.",starts={{npcID=69677,x=0.556,y=0.744,mapID=504}},ends={{npcID=69677,x=0.556,y=0.744,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32547] = {id=32547,name="The Creeping Carpet of Ihgaluk",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Ah, roaches! I once bought a pet roach in Booty Bay. Roaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far. Ihgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.",starts={{npcID=69677,x=0.556,y=0.744,mapID=504}},ends={{npcID=69677,x=0.556,y=0.744,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32548] = {id=32548,name="Left To Rot",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease. We can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.",starts={{npcID=69677,x=0.556,y=0.744,mapID=504}},ends={{npcID=69677,x=0.556,y=0.744,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32550] = {id=32550,name="Saur Loser",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6716,description="Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry. We need you to kill any Zandalari you find in the Beast Pens before they can get their mounted monstrosities out into the open battlefield.",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",zoneID=6507},questType="standard"},
[32551] = {id=32551,name="Compy Stomp",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The raptors and saurid of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares. I need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32552] = {id=32552,name="Loa-saur",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers. We need to put a stop to this. Search the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts. We must not allow these atrocities to continue.",starts={{npcID=67999,x=0.618,y=0.52,mapID=504}},ends={{npcID=67999,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32553] = {id=32553,name="Direhorn vs Devilsaur",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process. Within these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms. Go into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.",starts={{npcID=67999,x=0.618,y=0.52,mapID=504}},ends={{npcID=67999,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32554] = {id=32554,name="Dino Might",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts. Two can play at that game. I want you to find some of these fetishes and try them out on the various beasts in the Beast Pens. Take careful note of how each beast responds to each fetish. Then report your results to me. Maybe this will give us the edge we need against the Zandalari.",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32555] = {id=32555,name="Centuries in Sentries",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="Sacrifices are common place in Zandalari society. There is however one oddity among these barbaric rituals; volunteers. They treat it as a great honor! The weak still seek to contribute, even if that means giving their lives to be bound to the sentries you see walking around. Locked away in service to their people. Take this resonating crystal. Once destroyed, drain the sentry of its Zandalari inhabitant. Return the crystal to me when your task is complete.",starts={{npcID=67999,x=0.618,y=0.52,mapID=504}},ends={{npcID=67999,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",zoneID=6507},questType="standard"},
[32556] = {id=32556,name="The More You Know",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="This whole area is littered with Zandalari artifacts. I would be lying if I said studying them didn't interest me. I am fascinated by the significance of these objects to their rituals. The more we understand our enemies, the better prepared we are to defeat them. If I am to study them, I will need to see them up close. Bring me as many artifacts as you can find.",starts={{npcID=67999,x=0.618,y=0.52,mapID=504}},ends={{npcID=67999,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32557] = {id=32557,name="Out of Enemy Hands",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6757,mapID=554,description="Magic is a frightening opponent when wielded by an experienced caster. A blade however, is terrifying in even the most inexperienced hands. The Zandalari have some impressive weapons, made even more deadly by the magic they are enhanced with. We should relieve them of this advantage. Steal as many of the weapons as you can find.",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=554},questType="standard"},
[32558] = {id=32558,name="All In the Family",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Conqueror's Terrace is watched over by two brothers; Spiritbinder Tu'chek and Arcanital Rak'ul. They are powerful magic users and should not be underestimated. Their power seems to stem from the ornate masks they wear; relics passed down from one generation to the next. Each owner imbuing it with their own magic before passing it on. We must deal with the brothers and destroy their masks before they fall into the wrong hands.",starts={{npcID=67999,x=0.618,y=0.52,mapID=504}},ends={{npcID=67999,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32559] = {id=32559,name="Even Giants Fall",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Zandalari worship the loa; animal spirits they often call to their aid. They may be trying to bind these spirits into a huge golem. The outcome would be disastrous. I've sent ahead a scout to gather more information, but I think this task may require your expertise. Stop that ritual at all costs!",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32560] = {id=32560,name="Keep It Secret",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="The Zandalari here are a threat to our campaign, . Their use of magic is an abomination. They mix the power of arcane with the darkness of shadow with little care to consequence. We cannot afford for them to find their full strength here or for the Horde to learn of their twisted magic. Their numbers must be thinned. I will leave this task to you.",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",zoneID=6507},questType="standard"},
[32561] = {id=32561,name="Competing Magic",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="One of my scryers has identified a Zandalari leader near the central tower. He needs to be removed. Would you be willing to do this for me, ?",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32562] = {id=32562,name="Imposing Threat",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="One of my scouts has returned with word of a mogu leader under the central tower. He needs to be removed. Would you be willing to do this for me, ?",starts={{npcID=67660,x=0.468,y=0.668,mapID=504},{npcID=67989,x=0.384,y=0.512,mapID=504},{npcID=70520,x=0.368,y=0.648,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32563] = {id=32563,name="Encroaching Force",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We've spotted a Zandalari war party down on the beach just outside these walls. We need to eliminate them before returning to camp. Are you up for the task?",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32564] = {id=32564,name="Zandalari on the Rise",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp. Can you handle this one?",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32565] = {id=32565,name="Encroaching Force",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp. Would you be willing to handle this one?",starts={{npcID=67985,x=0.472,y=0.406,mapID=504}},ends={{npcID=67985,x=0.472,y=0.406,mapID=504}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32567] = {id=32567,name="The Beast Pens",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="I do not want to see another Zandalari beast rider breach our defenses! I have dispatched Scout Captain Daelin and some war mages to the Beast Pens northwest of here. Their mission is to infiltrate and harass the Zandalari siege and cavalry units. I want you to join them and lend your expertise. Keep an eye out for the tell tale shimmer of their magical cloaking spell.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32568] = {id=32568,name="No Time To Rest",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We have accomplished much since arriving here, but now is not the time to rest. Your efforts have helped us breach the upper level of the Thunder King's stronghold. Now, I call on you to continue our campaign. Report to Scout Captain Daelin within Conqueror's Terrace. He will have further orders for you.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32570] = {id=32570,name="Gather Scout Reports",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32571] = {id=32571,name="A Wing to Fly On",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="I've just received a report that another young pterrorwing has been spotted in the Diremoor. We need to recover as many of these as we can find. They may be the key to flying on this island.",starts={{npcID=67994,x=0.634,y=0.734,mapID=504}},ends={{npcID=67994,x=0.634,y=0.734,mapID=504}},coords={x=0.634,y=0.734,source="quest_giver",mapID=504},questType="standard"},
[32572] = {id=32572,name="The Sleepless Legion",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="standard"},
[32573] = {id=32573,name="Enemies Beneath the Tower",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6716,description="There are mogu in the Diremoor animating the army of statues near the tower. Vereesa wants them dead. I think you're the one to do it.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",zoneID=6507},questType="standard"},
[32574] = {id=32574,name="The Shuddering Moor",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate. Strike it down before it grows hungry enough to brave our defenses.",starts={{npcID=67993,x=0.632,y=0.722,mapID=504}},ends={{npcID=67993,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32575] = {id=32575,name="The Zandalari Colossus",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, .",starts={{npcID=67993,x=0.632,y=0.722,mapID=504}},ends={{npcID=67993,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32576] = {id=32576,name="Competing Magic",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="One of the scryers has identified a Zandalari leader near the central tower. He needs to be removed. Would you be willing to handle this?",starts={{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32577] = {id=32577,name="Imposing Threat",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="One of Vereesa's scouts has returned with word of a mogu leader under the central tower. He needs to be removed. Would you be willing to handle this?",starts={{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32578] = {id=32578,name="Among the Bones",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. We need someone capable to see him dispatched. Are you up to the task?",starts={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32579] = {id=32579,name="Competing Magic",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The scouts have spotted a dangerous Zandalari just this side of Za'Tual. We need someone capable to see him dispatched. Are you up to the task?",starts={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32580] = {id=32580,name="Encroaching Force",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We've received word of a Zandalari war party up the beach, north of our foothold. We need them hunted down and killed. Are you willing to do this thing for us, ?",starts={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32581] = {id=32581,name="Imposing Threat",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The scryers have spotted a mogu leader at the central tower. He needs to be killed before he can mount an offensive on our position. Can you take care of this for us?",starts={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=67996,x=0.556,y=0.744,mapID=504},{npcID=67997,x=0.402,y=0.594,mapID=504},{npcID=70517,x=0.422,y=0.664,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32582] = {id=32582,name="Raining Bones",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp. Would you be willing to do the deed?",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32583] = {id=32583,name="Zandalari on the Rise",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp. Can you handle this one?",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32585] = {id=32585,name="Encroaching Force",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp. Would you be willing to handle this one?",starts={{npcID=67998,x=0.618,y=0.52,mapID=504}},ends={{npcID=67998,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32586] = {id=32586,name="Maximum Capacitor",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The mines north of here are critical to the mogu supply line. They are using giant lightning enchanted drills to extract the ore. If you can disrupt the drills, they'll be destroyed, greatly slowing their ability to make weapons. Oh, also, kill whoever is in charge, will you?",starts={{npcID=67999,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32587] = {id=32587,name="Forge Ahead!",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability. And beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city. It's time to move out!",ends={{npcID=70552,x=0.586,y=0.426,mapID=504}},questType="standard"},
[32588] = {id=32588,name="On Her Magic-ey Secret Service",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Under orders from Jaina herself, some of our agents attempted to sneak past mogu lines to find out what was going on in the mines. They were captured, and are being subjected to who-knows-what kind of awful tortures. You must free them and kill whoever captured them. We don't leave anyone behind!",starts={{npcID=67999,x=0.618,y=0.52,mapID=504}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32603] = {id=32603,name="Beasts of Fable",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,description="Have you ever read the great Pandaren book of fables? Pandaren pass these stories on to their cubs - stories of the cricket and the hawk, or the slow-moving turtle - to teach them lessons that they will find useful in life. What few cubs know is that these creatures exist, here, in Pandaria! Though the stories of their travels are made up, they are powerful denizens of this world. Should you happen upon them in your travels, you may test the might of your pets against their storied statures.",starts={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},ends={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},coords={x=0.864,y=0.6,source="quest_giver",mapID=418},questType="standard"},
[32604] = {id=32604,name="Beasts of Fable Book I",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5841,mapID=379,description="The stories of Ka'wi the Gorger , Nitun , Kafi , and Dos-Ryga will exist in this land, always. Do you wish to meet them in battle once more?",starts={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},ends={{npcID=64572,x=0.864,y=0.6,mapID=1530},{npcID=64582,x=0.608,y=0.236,mapID=1530}},coords={x=0.864,y=0.6,source="quest_giver",mapID=379},questType="standard"},
[32605] = {id=32605,name="Subtle Encouragement",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men. We've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Horde lives.",starts={{npcID=67660,x=0.468,y=0.668,mapID=504}},ends={{npcID=67660,x=0.468,y=0.668,mapID=504}},coords={x=0.468,y=0.668,source="quest_giver",mapID=504},questType="standard"},
[32606] = {id=32606,name="Subtle Encouragement",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men. We've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Alliance lives.",starts={{npcID=67996,x=0.556,y=0.744,mapID=504}},ends={{npcID=67996,x=0.556,y=0.744,mapID=504}},coords={x=0.556,y=0.744,source="quest_giver",mapID=504},questType="standard"},
[32607] = {id=32607,name="Extended Shore Leave",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort. Simply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault. No captain. No repairs. No warship.",starts={{npcID=69413,x=0.586,y=0.426,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.586,y=0.426,source="quest_giver",mapID=504},questType="standard"},
[32608] = {id=32608,name="Raiding the Vault",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same. One artifact in particular, an amulet known as the Choker of Storms , could help us to understand his apparent mastery over lightning. Break into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.",questType="standard"},
[32609] = {id=32609,name="Rare Chest Tracking Quest",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32610] = {id=32610,name="Rare Boss Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32611] = {id=32611,name="Rare Drop Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32618] = {id=32618,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=12,mapID=37,description="It's time for you to learn how to ride! Seek out Randal Hunter at the Eastvale Logging Camp in Elwynn Forest. Don't forget to buy your mount while you are there!",ends={{npcID=4732,x=0.842,y=0.65,mapID=37}},questType="standard"},
[32622] = {id=32622,name="Intro Flight",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32626] = {id=32626,name="Loot Room Key Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32627] = {id=32627,name="Charged Moganite",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We have been dispatching spies into the Sunreaver base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here. They have not returned, and I can confirm they have left the Sunreaver base. Search the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.",starts={{npcID=67994,x=0.634,y=0.734,mapID=504}},ends={{npcID=67994,x=0.634,y=0.734,mapID=504}},coords={x=0.634,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32628] = {id=32628,name="Tactical Mana Bombs",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Ah, $p, just the I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest. Here, take these. It is time to give the Sunreavers a taste of their own medicine. Plant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32629] = {id=32629,name="Thunderwing Captured Tracking Quest",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32631] = {id=32631,name="High Recognition",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32632] = {id=32632,name="Made for War",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Some things are built with multiple purposes in mind. Some things are built with the sole purpose of destruction. A massive construct called the Pyrestar Demolisher sits guarding Dawnseeker Promontory. Its purpose is solely to destroy. It must be dismantled.",starts={{npcID=67994,x=0.634,y=0.734,mapID=504}},ends={{npcID=67994,x=0.634,y=0.734,mapID=504}},coords={x=0.634,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32633] = {id=32633,name="Spellbound",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Grand Magister Rommath has something in his possession that I want. He brought a very powerful tome with him. It would be better for our cause if it were no longer in Sunreaver hands. Locate Rommath's book of incantations and bring it to me.",starts={{npcID=67994,x=0.634,y=0.734,mapID=504}},ends={{npcID=67994,x=0.634,y=0.734,mapID=504}},coords={x=0.634,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32634] = {id=32634,name="Breaking Down the Defenses",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Even the strongest defense can still have a weakness, . We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible. Scouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly. Disabling them would allow us to keep closer watch on their activities.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32635] = {id=32635,name="Enough with the Bombs!",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Sunreavers have planted tactical mana bombs around our camp. These must be dismantled before they are detonated. Look for them in areas of high importance such as our supplies. Make sure you find and disable them all. We cannot afford to lose any ground here.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32636] = {id=32636,name="Captive Audience",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Sunreavers will stoop to even the lowest levels to get what they want, . I received reports earlier that several Kirin Tor have gone missing. I suspect the Sunreavers may have something to do with this. Hopefully they have not been harmed, or my wrath will be swift and terrible. I trust you to bring them back in one piece, but please hurry.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32637] = {id=32637,name="Overpowered",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Sunreaver forces have grown more powerful recently. I suspect magic to be at play here, but I can't be certain. I think it would be wise to investigate their camp to see if you can find the source of this extra power. Once you find it, use this crystal to overload and destroy it.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32638] = {id=32638,name="Mana Scavengers",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Sometimes, even the smallest creatures can be the biggest threat. The Sunreavers brought mana wyrms with them. Though small in size they have the ability to cripple our casters in combat. Many have learned the hard way not to underestimate them. They must be dealt with and quickly.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32639] = {id=32639,name="Deconstruction",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Scouts are reporting a large number of constructs patrolling outside of Dawnseeker Promontory. If left unchecked they will pose a considerable threat should the Sunreavers mount an attack. The only answer is a preemptive strike. We'll destroy them before they can attack us!",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32640] = {id=32640,name="Champions of the Thunder King",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities. If you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them. Find and destroy members of each group to keep them destabilized, and I will make it worth your time.",starts={{npcID=70160,x=0.514,y=0.46,mapID=504}},ends={{npcID=70160,x=0.514,y=0.46,mapID=504}},coords={x=0.514,y=0.46,source="quest_giver",mapID=504},questType="group"},
[32645] = {id=32645,name="Work Order: Operation: Shieldwall I",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,starts={{npcID=218750,x=0.522,y=0.487,mapID=376}},coords={x=0.522,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32648] = {id=32648,name="Work Order: Golden Lotus II",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Well, hopefully these crops will be suitable! Once your white turnips are ready to be picked, you'll need only to package them for pick-up.",starts={{npcID=218765,x=0.517,y=0.487,mapID=376}},ends={{npcID=218765,x=0.517,y=0.487,mapID=376}},coords={x=0.517,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32649] = {id=32649,name="Work Order: Shado-Pan I",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=218750,x=0.522,y=0.487,mapID=376}},coords={x=0.522,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32652] = {id=32652,name="To the Skies!",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="We have a plan to halt the mogu's weaponmaking capabilities, and it involves the creature you recovered from the Zandalari. Speak to me when you're ready to learn more.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=69741,x=0.632,y=0.738,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32655] = {id=32655,name="A Bold Idea",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army. If we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure. I have a plan to do just that, and it won't take an entire army.",starts={{npcID=70297,x=0.632,y=0.738,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.738,source="quest_giver",mapID=504},questType="standard"},
[32656] = {id=32656,name="The Fall of Shan Bu",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="Lei Shen found a clutch of rare storm dragon eggs early in his campaign. One - known as Nalak - was particularly brutal and killed all of its handlers, so he took it for his own. Now, Shan Bu , one of Lei Shen's most loyal servants, works to resurrect the dragon. It is time for us to strike against Shan Bu ! Speak to me when you are ready to launch the assault!",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32658] = {id=32658,name="Work Order: The Klaxxi I",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=218750,x=0.522,y=0.487,mapID=376}},coords={x=0.522,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32662] = {id=32662,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1,mapID=27,description="It's time for you to learn how to ride! Seek out Ultham at the Amberstill Ranch in Dun Morogh, along the road east out of Ironforge. Don't forget to buy your mount while you are there!",ends={{npcID=4772,x=0.712,y=0.484,mapID=27}},questType="standard"},
[32663] = {id=32663,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1,mapID=27,description="It's time for you to learn how to ride! Seek out Binjy Featherwhistle at the Steelgrill's Depot in Dun Morogh. Don't forget to buy your mount while you are there!",ends={{npcID=7954,x=0.562,y=0.464,mapID=27}},questType="standard"},
[32664] = {id=32664,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1657,mapID=89,description="It's time for you to learn how to ride! Seek out Jartsam at the Cenarion Enclave in Darnassus. Don't forget to buy your mount while you are there!",ends={{npcID=4753,x=0.546,y=0.122,mapID=84},{npcID=4753,x=0.426,y=0.33,mapID=89}},questType="standard"},
[32665] = {id=32665,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="It's time for you to learn how to ride! Seek out Mei Lin north of the Dwarven District in Stormwind. Don't forget to buy your mount while you are there!",ends={{npcID=70296,x=0.676,y=0.186,mapID=84}},questType="standard"},
