[32669] = {id=32669,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,mapID=85,description="It's time for you to learn how to ride! Seek out Kildar in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!",ends={{npcID=4752,x=0.614,y=0.344,mapID=85}},questType="standard"},
[32670] = {id=32670,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=215,mapID=7,description="It's time for you to learn how to ride! Seek out Kar Stormsinger in Mulgore's Bloodhoof Village. Don't forget to buy your mount while you are there!",ends={{npcID=3690,x=0.476,y=0.58,mapID=7}},questType="standard"},
[32671] = {id=32671,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=14,mapID=1,description="It's time for you to learn how to ride! Seek out Xar'Ti at Sen'jin Village in southern Durotar. Don't forget to buy your mount while you are there!",ends={{npcID=7953,x=0.552,y=0.754,mapID=1}},questType="standard"},
[32672] = {id=32672,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=85,mapID=18,description="It's time for you to learn how to ride! Seek out Velma Warnam at Brill in Tirisfal Glades. Don't forget to buy your mount while you are there!",ends={{npcID=4773,x=0.618,y=0.518,mapID=18}},questType="standard"},
[32673] = {id=32673,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,mapID=85,description="It's time for you to learn how to ride! Seek out Revi Ramrod in Orgrimmar's Valley of Spirits. Don't forget to buy your mount while you are there!",ends={{npcID=48513,x=0.366,y=0.87,mapID=85}},questType="standard"},
[32674] = {id=32674,name="I Believe You Can Fly",level=30,requiredLevel=30,faction="horde",expansion=4,zoneID=1637,mapID=85,description="The skies call out to you! It's time to learn to fly! Visit the flying trainer, Maztha , at the Skyway in Orgrimmar. And don't forget to buy a flying mount!",ends={{npcID=44919,x=0.49,y=0.592,mapID=85}},questType="standard"},
[32675] = {id=32675,name="I Believe You Can Fly",level=30,requiredLevel=30,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="The skies call out to you! It's time to learn to fly! Visit the flying trainer, Bralla Cloudwing , at the Gryphon Roost in Stormwind. And don't forget to buy a flying mount!",ends={{npcID=43769,x=0.702,y=0.734,mapID=84}},questType="standard"},
[32676] = {id=32676,name="Extended Shore Leave",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort. Simply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault. No captain. No repairs. No warship.",starts={{npcID=69413,x=0.586,y=0.426,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.586,y=0.426,source="quest_giver",mapID=504},questType="standard"},
[32677] = {id=32677,name="Raiding the Vault",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same. One artifact in particular, an amulet known as the Choker of Storms , could help us to understand his apparent mastery over lightning. Break into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.",questType="standard"},
[32686] = {id=32686,name="Pristine Banner of the Mantid Empire",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=9105,mapID=1530,description="This artifact has been restored to a remarkably excellent condition. Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.",ends={{npcID=218958,x=0.828,y=0.322,mapID=1530},{npcID=218958,x=0.833,y=0.297,mapID=1530}},questType="standard"},
